  lines = {
    { id = "area:1086:text", html = false,
      ja = "Toxic Foggerを設置する",
      out = "トキシック・フォガーを設置する" },
    { id = "area:7843:text", html = false,
      ja = "Wildhammerへの伝言を届けた",
      out = "ワイルドハンマーへの伝言を届けた" },
    { id = "book:1031:text", html = true,
      ja = "<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P>\n我が敬愛する師、Horatio M. Montgomery, M.D.を偲んで。治療師、Teacher、友。\n</P>\n<BR/>\n<H1 align=\"center\">\n50 BTFT - 25 ATFT\n</H1>\n<BR/>\n<P>\n「世界は病める者と疲れ果てた者で満ちている。治療師として、いや、医学に携わる男として女として、その『itis』を彼らすべてから一掃することこそ、我々の務めなのだ。」 \n</P>\n<BR/>\n<P>\n- H.M.M., M.D., PhD, JD, Grandmaster Farmer, Dancer Extraordinaire, Animalsの友\n</P>\n<BR/>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P>\n我が敬愛する師、ホレイショ・エム・モンゴメリー, エム・ディー.を偲んで。治療師、ティーチャー、友。\n</P>\n<BR/>\n<H1 align=\"center\">\n50 ビーティーエフティー - 25 エーティーエフティー\n</H1>\n<BR/>\n<P>\n「世界は病める者と疲れ果てた者で満ちている。治療師として、いや、医学に携わる男として女として、その『イティス』を彼らすべてから一掃することこそ、我々の務めなのだ。」 \n</P>\n<BR/>\n<P>\n- エイチ・エム・エム., エム・ディー., ピーエイチディー, ジェイディー, グランドマスター・ファーマー, ダンサー・エクストラオーディネール, アニマルの友\n</P>\n<BR/>\n</BODY>\n</HTML>" },
    { id = "book:1514:text", html = true,
      ja = "<HTML>\n<BODY>\n<H1 align=\"center\">\n第2章：Eastern Pylon\n</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_mini_east\" align=\"left\"/>\n<P align=\"right\">Eastern<BR/>\nPylonは<BR/>\n青、黄、<BR/>\n緑の<BR/>\nクリスタルを受け入れる。</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align=\"left\">Pylonは、青いクリスタルを主な動力源として生み出されるエネルギーに集中する。</P>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<H1 align=\"center\">\n第2章：イースタン・パイロン\n</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_mini_east\" align=\"left\"/>\n<P align=\"right\">イースタン<BR/>\nパイロンは<BR/>\n青、黄、<BR/>\n緑の<BR/>\nクリスタルを受け入れる。</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align=\"left\">パイロンは、青いクリスタルを主な動力源として生み出されるエネルギーに集中する。</P>\n</BODY>\n</HTML>" },
    { id = "book:1533:text", html = true,
      ja = "<HTML>\n<BODY>\n<H1 align=\"center\">\nWESTERN PYLON 配置図\n</H1>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_west\"/>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<H1 align=\"center\">\nウェスタン・パイロン 配置図\n</H1>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_west\"/>\n</BODY>\n</HTML>" },
    { id = "book:15:text", html = false,
      ja = "Morganへ\n\nGoldshireの商売は繁盛していて、あまりの忙しさに、そちらへ荷を送る暇もありませんでした！\n\nこの手紙を届けた方に、大きな蝋燭をひと包み、そちらへ運んでもらうよう依頼しました（ほら、Koboldsが好んで頭にのせている、あの蝋燭です）。\n\nどうかこの方に私たちからの感謝を伝え、正当な報酬を払ってあげてください。",
      out = "モーガンへ\n\nゴールドシャイアの商売は繁盛していて、あまりの忙しさに、そちらへ荷を送る暇もありませんでした！\n\nこの手紙を届けた方に、大きな蝋燭をひと包み、そちらへ運んでもらうよう依頼しました（ほら、コボルドが好んで頭にのせている、あの蝋燭です）。\n\nどうかこの方に私たちからの感謝を伝え、正当な報酬を払ってあげてください。" },
    { id = "book:1881:text", html = false,
      ja = "Arathorianの二番目の都市国家であるDalaranは、Stromの北の地に建設された。駆け出しの魔法使いの多くが、Stromの窮屈な束縛を後にしてDalaranへと向かい、そこで新たな力をより自由に使うことを望んだ。この魔術師たちはその技を用いてDalaranの魔力を帯びた尖塔を築き上げ、研究の探求に耽った。",
      out = "アラソールの二番目の都市国家であるダラランは、ストロームの北の地に建設された。駆け出しの魔法使いの多くが、ストロームの窮屈な束縛を後にしてダラランへと向かい、そこで新たな力をより自由に使うことを望んだ。この魔術師たちはその技を用いてダラランの魔力を帯びた尖塔を築き上げ、研究の探求に耽った。" },
    { id = "book:2012:text", html = false,
      ja = "Kil'jaedenはNer'zhulの氷の器をAzerothの世界へと投げ落とした。硬い水晶は夜空を横切り、荒涼とした極北の大陸Northrendに激突して、Icecrownの氷河の奥深くに埋まった。激しい落下によって歪み傷ついた凍てつく水晶は玉座のような姿となり、やがてその中でNer'zhulの復讐に燃える魂が目覚めた。",
      out = "キルジェイデンはネルズールの氷の器をアゼロスの世界へと投げ落とした。硬い水晶は夜空を横切り、荒涼とした極北の大陸ノースレンドに激突して、アイスクラウンの氷河の奥深くに埋まった。激しい落下によって歪み傷ついた凍てつく水晶は玉座のような姿となり、やがてその中でネルズールの復讐に燃える魂が目覚めた。" },
    { id = "book:2216:text", html = false,
      ja = "幸運を祈る。そして、Urokの手下との試練に役立つかもしれぬ手がかりを授けよう。\n\nOmokkがogreに対して使う呪文、奴らを打ち殺すあの呪文は、Omokkを殺した後もなお力を持っているかもしれぬ。Urokの手下との戦いの最中に、Omokkの首に宿る力を呼び起こせ――運が良ければ、OmokkがUrokの手下どもを打ち倒すであろう！\n\nなんともふさわしい皮肉よ。",
      out = "幸運を祈る。そして、ウロクの手下との試練に役立つかもしれぬ手がかりを授けよう。\n\nオモックがオーガに対して使う呪文、奴らを打ち殺すあの呪文は、オモックを殺した後もなお力を持っているかもしれぬ。ウロクの手下との戦いの最中に、オモックの首に宿る力を呼び起こせ――運が良ければ、オモックがウロクの手下どもを打ち倒すであろう！\n\nなんともふさわしい皮肉よ。" },
    { id = "book:2637:text", html = false,
      ja = "Foror's Compendium of Dragon Slayingは、文字がびっしりと書かれた分厚い本だ。あいにく文章は乱れていて、まったく意味がわからない。",
      out = "フォラーズ・コンペンディウム・オブ・ドラゴン・スレイイングは、文字がびっしりと書かれた分厚い本だ。あいにく文章は乱れていて、まったく意味がわからない。" },
    { id = "book:2660:text", html = true,
      ja = "<HTML> <BODY> <H1 align=\"center\">Hordeの下士官・兵の階級</H1><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank01\"/><BR/> <P align=\"right\">First Sergeant</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank04\"/><BR/> <P align=\"right\">Senior Sergeant</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank03\"/><BR/> <P align=\"right\">Sergeant</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank02\"/><BR/> <P align=\"right\">兵卒</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank01\"/><BR/> <P align=\"right\">斥候</P><BR/><BR/> </BODY> </HTML>",
      out = "<HTML> <BODY> <H1 align=\"center\">ホードの下士官・兵の階級</H1><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank01\"/><BR/> <P align=\"right\">ファースト・サージェント</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank04\"/><BR/> <P align=\"right\">シニア・サージェント</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank03\"/><BR/> <P align=\"right\">サージェント</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank02\"/><BR/> <P align=\"right\">兵卒</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank01\"/><BR/> <P align=\"right\">斥候</P><BR/><BR/> </BODY> </HTML>" },
    { id = "book:2676:text", html = true,
      ja = "<HTML>\n<BODY>\n<H1 align=\"center\">ALLIANCEの軍階級</H1><BR/>\n<P align=\"center\">士官</P><BR/>\n<P align=\"center\">Grand Marshal</P>\n<P align=\"center\">Field Marshal</P>\n<P align=\"center\">Marshal</P>\n<P align=\"center\">Commander</P>\n<P align=\"center\">Lieutenant Commander</P>\n<P align=\"center\">Knight-Champion</P>\n<P align=\"center\">Knight-Captain</P>\n<P align=\"center\">Knight-Lieutenant</P>\n<P align=\"center\">Knight</P><BR/>\n<P align=\"center\">下士官・兵</P><BR/>\n<P align=\"center\">Sergeant Major</P>\n<P align=\"center\">Master Sergeant</P>\n<P align=\"center\">Sergeant</P>\n<P align=\"center\">Corporal</P>\n<P align=\"center\">Private</P>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<H1 align=\"center\">アライアンスの軍階級</H1><BR/>\n<P align=\"center\">士官</P><BR/>\n<P align=\"center\">グランド・マーシャル</P>\n<P align=\"center\">フィールド・マーシャル</P>\n<P align=\"center\">マーシャル</P>\n<P align=\"center\">コマンダー</P>\n<P align=\"center\">ルテナント・コマンダー</P>\n<P align=\"center\">ナイト・チャンピオン</P>\n<P align=\"center\">ナイト・キャプテン</P>\n<P align=\"center\">ナイト・ルテナント</P>\n<P align=\"center\">ナイト</P><BR/>\n<P align=\"center\">下士官・兵</P><BR/>\n<P align=\"center\">サージェント・メジャー</P>\n<P align=\"center\">マスター・サージェント</P>\n<P align=\"center\">サージェント</P>\n<P align=\"center\">コーポラル</P>\n<P align=\"center\">プライベート</P>\n</BODY>\n</HTML>" },
    { id = "book:2856:text", html = true,
      ja = "<HTML>\n<BODY>\n<H1 align=\"center\">ALLIANCEの士官階級</H1><BR/>\n<P align=\"center\">第2部</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>\n<P align=\"right\">騎士長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>\n<P align=\"right\">騎士隊長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>\n<P align=\"right\">騎士副官</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>\n<P align=\"right\">騎士</P><BR/><BR/>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<H1 align=\"center\">アライアンスの士官階級</H1><BR/>\n<P align=\"center\">第2部</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>\n<P align=\"right\">騎士長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>\n<P align=\"right\">騎士隊長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>\n<P align=\"right\">騎士副官</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>\n<P align=\"right\">騎士</P><BR/><BR/>\n</BODY>\n</HTML>" },
    { id = "book:2889:text", html = false,
      ja = "ごきげんよう。あなたがScourgeから見つけたあの書簡を、ようやく調べる時間ができました。少々手間はかかりましたが、亡くなった方の存命の親族を見つけられたと思います。\n\nMaxwellの姉妹、Zarena Cromwindという人物が、Booty Bayで小さな武器屋を営んでいます。兄弟とどれほど親しかったかは分かりませんが、近くを通りかかることがあれば、会う機会を作るとよいでしょう。こうした事柄に区切りをつけられることは、今の時代、貴重でめったにないことですから。",
      out = "ごきげんよう。あなたがスコージから見つけたあの書簡を、ようやく調べる時間ができました。少々手間はかかりましたが、亡くなった方の存命の親族を見つけられたと思います。\n\nマクスウェルの姉妹、ザレナ・クロムウィンドという人物が、ブーティ・ベイで小さな武器屋を営んでいます。兄弟とどれほど親しかったかは分かりませんが、近くを通りかかることがあれば、会う機会を作るとよいでしょう。こうした事柄に区切りをつけられることは、今の時代、貴重でめったにないことですから。" },
    { id = "book:41:text", html = false,
      ja = "Lord Stoutmantle——\n\nEdwin VanCleefが率いたStonemason's Guildは、人間の中でも最も腕の立つ建築者たちで構成されていました。Stonemasonsは、First Warの際にオークによって焼き払われたStormwindの街の再建に力を尽くしました。VanCleefと彼の職人たちは比類なき建築者であり、その仕事と技巧はCathedral of LightやStormwind Keepそのものの建物に表れています。",
      out = "ロード・スタウトマントル——\n\nエドウィン・ヴァンクリーフが率いたストーンメイソンズ・ギルドは、人間の中でも最も腕の立つ建築者たちで構成されていました。ストーンメイソンは、ファースト・ウォーの際にオークによって焼き払われたストームウィンドの街の再建に力を尽くしました。ヴァンクリーフと彼の職人たちは比類なき建築者であり、その仕事と技巧はカテドラル・オブ・ライトやストームウィンド・キープそのものの建物に表れています。" },
    { id = "book:795:text", html = false,
      ja = "Old Godsはわれらの世界の意志である。あらゆる嵐の中にOld Godの笑い声が轟く。山火事の炎は彼らの眼差しの熱である。Old Godsが歩めば大地は震えて裂け、より弱き者たちは絶望のあまり叫び、自らの肉を引き裂く。\n\nそして絶望するのも当然である。火が子どもの好奇心に満ちた手に容赦しないように、Old Godsは自らの下にいる者たちを何ら顧みないからだ。よくて、われらは駒である。悪くすれば、玩具である。",
      out = "オールド・ゴッドはわれらの世界の意志である。あらゆる嵐の中にオールド・ゴッドの笑い声が轟く。山火事の炎は彼らの眼差しの熱である。オールド・ゴッドが歩めば大地は震えて裂け、より弱き者たちは絶望のあまり叫び、自らの肉を引き裂く。\n\nそして絶望するのも当然である。火が子どもの好奇心に満ちた手に容赦しないように、オールド・ゴッドは自らの下にいる者たちを何ら顧みないからだ。よくて、われらは駒である。悪くすれば、玩具である。" },
    { id = "gossip:03c8094081cbc743:text", html = false,
      ja = "Dhugru Gorelustは町の東側にある兵舎の裏に隠れている。お前がBurning Legionとつるんでいるなんてことが分かったら、ただじゃおかないぞ!",
      out = "ドゥグル・ゴアラストは町の東側にある兵舎の裏に隠れている。お前がバーニング・レギオンとつるんでいるなんてことが分かったら、ただじゃおかないぞ!" },
    { id = "gossip:099573ea33ea20af:text", html = false,
      ja = "Wolf Ridingの細かいコツを教えてやれるぞ。授業料の金貨を払えればの話だがな！",
      out = "ウルフ・ライディングの細かいコツを教えてやれるぞ。授業料の金貨を払えればの話だがな！" },
    { id = "gossip:1022846a66423d8b:text", html = false,
      ja = "私は多くを知っていますが、見知らぬ方、あなたの知識は私に匹敵します。さらに腕を磨きたい付呪師は、Kitta Firewindという匠が住むTower of Azoraを訪ねるそうですよ。",
      out = "私は多くを知っていますが、見知らぬ方、あなたの知識は私に匹敵します。さらに腕を磨きたい付呪師は、キッタ・ファイアウィンドという匠が住むタワー・オブ・アゾラを訪ねるそうですよ。" },
    { id = "gossip:16a618744777c340:text", html = false,
      ja = "%sはStalaggの救援に駆けつけた！",
      out = "%sはスタラグの救援に駆けつけた！" },
    { id = "gossip:1cc47f2d9711f5dd:text", html = false,
      ja = "Yonn DeepcutはBloodhoof Villageの北西の隅にある大きなテントの中にいます。",
      out = "ヨン・ディープカットはブラッドフーフ・ヴィレッジの北西の隅にある大きなテントの中にいます。" },
    { id = "gossip:22eac5b1bebdcc1f:text", html = false,
      ja = "%sは倒れゆくCaptain Beltisへ手を伸ばした。",
      out = "%sは倒れゆくキャプテン・ベルティスへ手を伸ばした。" },
    { id = "gossip:2875be427c4e9207:text", html = false,
      ja = "そしてこれがComar Villardだ。結婚してわずか2週間で、妻が安全なはずのMenethil Harborからさらわれてしまった。",
      out = "そしてこれがコマー・ヴィラードだ。結婚してわずか2週間で、妻が安全なはずのメネシル・ハーバーからさらわれてしまった。" },
    { id = "gossip:2f3b7a3810dfb218:text", html = false,
      ja = "このkodo、最初におびき寄せた獣とは似ても似つかないな！ kombobulatorを自分に使えないもんかな。",
      out = "このコドー、最初におびき寄せた獣とは似ても似つかないな！ コンボビュレーターを自分に使えないもんかな。" },
    { id = "gossip:3481b5cc37605013:text", html = false,
      ja = "Engineering",
      out = "エンジニアリング" },
    { id = "gossip:3a58b3410c36b1d6:text", html = false,
      ja = "Scourgeがこのあたりで暴れ回っていちゃ、何もできやしない！",
      out = "スコージがこのあたりで暴れ回っていちゃ、何もできやしない！" },
    { id = "gossip:3f8c3578ad2106fd:text", html = false,
      ja = "今朝、Ravenholdtからの使者たちがこの手紙を届けてきた。お前宛てだ、{name}。",
      out = "今朝、レイヴンホルトからの使者たちがこの手紙を届けてきた。お前宛てだ、{name}。" },
    { id = "gossip:4604c89ae9e33346:text", html = false,
      ja = "本当に驚いているのですか？ Old Godの力がDreamの内側にまで及びうるとは、信じがたいですか？ それは事実です。Eranikus, Tyrant of the Dreamが、私たち皆に戦いを仕掛けているのです。彼が破壊を撒き散らした跡を、Nightmareが追っているのです。",
      out = "本当に驚いているのですか？ オールド・ゴッドの力がドリームの内側にまで及びうるとは、信じがたいですか？ それは事実です。エラニカス, タイラント・オブ・ザ・ドリームが、私たち皆に戦いを仕掛けているのです。彼が破壊を撒き散らした跡を、ナイトメアが追っているのです。" },
    { id = "gossip:4b1e2440b561472d:text", html = false,
      ja = "Hordeが欲しがってる分のlean wolf steakはもう揃ったみたいだ。ここにある分をまとめて、SilithusのCenarion Holdへ出荷する準備をしろって言われたよ。でも、ここにいる他の連中の中には、担当してる何かをまだ集めてる奴もいるみたいだ。そっちに声をかけてみな。",
      out = "ホードが欲しがってる分のリーン・ウルフ・ステーキはもう揃ったみたいだ。ここにある分をまとめて、シリサスのセナリウス・ホールドへ出荷する準備をしろって言われたよ。でも、ここにいる他の連中の中には、担当してる何かをまだ集めてる奴もいるみたいだ。そっちに声をかけてみな。" },
    { id = "gossip:5213a7ce7ac32eec:text", html = false,
      ja = "精霊の導きにもう少しよく耳を傾けねばならんぞ、若いの。お前の道は別の者と共にある。Thunder BluffのThrag Stonehoofだ。互いに何かを学び合えるかもしれん。",
      out = "精霊の導きにもう少しよく耳を傾けねばならんぞ、若いの。お前の道は別の者と共にある。サンダー・ブラフのスラグ・ストーンフーフだ。互いに何かを学び合えるかもしれん。" },
    { id = "gossip:5829558283463b5b:text", html = false,
      ja = "やあ、旅の人。目は悪くなったが、{class}の足音なら一マイル先からでも分かる。何年もの間、誇りを持ってStormwindを守ってきたが、目が利かなくなって引退を余儀なくされたのだ。",
      out = "やあ、旅の人。目は悪くなったが、{class}の足音なら一マイル先からでも分かる。何年もの間、誇りを持ってストームウィンドを守ってきたが、目が利かなくなって引退を余儀なくされたのだ。" },
    { id = "gossip:5e705df171f26016:text", html = false,
      ja = "大釜を覗き込むのだ、{name}。Margが話したがっている……",
      out = "大釜を覗き込むのだ、{name}。マーグが話したがっている……" },
    { id = "gossip:63eb893478cf6f9f:text", html = false,
      ja = "Eyeに導かれてここへ来ました、Eris。",
      out = "アイに導かれてここへ来ました、エリス。" },
    { id = "gossip:6a0db92916a30be6:text", html = false,
      ja = "ここにいると退屈することもあるのよ。あの堅物のHalaanをからかうのにも、そのうち飽きてしまうし。",
      out = "ここにいると退屈することもあるのよ。あの堅物のハラーンをからかうのにも、そのうち飽きてしまうし。" },
    { id = "gossip:6fab26eb50a940c8:text", html = false,
      ja = "%sはRune of Escapeを目の前に掲げた。",
      out = "%sはルーン・オブ・エスケープを目の前に掲げた。" },
    { id = "gossip:7554b2bae0ae97d9:text", html = false,
      ja = "この月光があなたをThunder Bluffへ運びます。祭りを去りたいときに使ってください。",
      out = "この月光があなたをサンダー・ブラフへ運びます。祭りを去りたいときに使ってください。" },
    { id = "gossip:7a4f264e86866aea:text", html = false,
      ja = "%sはGlowing Fruitから種を取り除いた……",
      out = "%sはグローイング・フルーツから種を取り除いた……" },
    { id = "gossip:805b501ade850228:text", html = false,
      ja = "やあ、Belm！Thunder Aleを一杯くれ、それと良き友の{name}にも一杯だ。",
      out = "やあ、ベルム！サンダー・エールを一杯くれ、それと良き友の{name}にも一杯だ。" },
    { id = "gossip:873bbd121f923a1f:text", html = false,
      ja = "不快な場所だな、この「Undercity」というのは。昔のLordaeronとは似ても似つかぬ。あの頃が懐かしい……\n\nStratholmeへ行きたいのなら、あいにく今はお力になれない。燃える街の近くの塔はまだ争奪戦の最中で、そのため私の力はあまりに弱く、あなたを助けられないのだ。あちらで勝利したら、また私のところへ来てくれ。",
      out = "不快な場所だな、この「アンダーシティ」というのは。昔のローデロンとは似ても似つかぬ。あの頃が懐かしい……\n\nストラトホルムへ行きたいのなら、あいにく今はお力になれない。燃える街の近くの塔はまだ争奪戦の最中で、そのため私の力はあまりに弱く、あなたを助けられないのだ。あちらで勝利したら、また私のところへ来てくれ。" },
    { id = "gossip:8cd460d0c8d2abe6:text", html = false,
      ja = "impについて学ぶ機会はもう十分あっただろう。次は、あなたが召喚できるようになる次の従僕、voidwalkerに移りましょう。",
      out = "インプについて学ぶ機会はもう十分あっただろう。次は、あなたが召喚できるようになる次の従僕、ヴォイドウォーカーに移りましょう。" },
    { id = "gossip:9378095819b6fe6b:text", html = false,
      ja = "私たちはCenariusの教えに従い、均衡を守るために働いています、{class}。彼の光は私たちに道を示す灯台の明かりであり、私たちはその光を守るために全力を尽くさねばなりません。",
      out = "私たちはセナリウスの教えに従い、均衡を守るために働いています、{class}。彼の光は私たちに道を示す灯台の明かりであり、私たちはその光を守るために全力を尽くさねばなりません。" },
    { id = "gossip:98e3d2c218fea9b9:text", html = false,
      ja = "すまんな、若いの。お前にはまだ、わしが教えることを学ぶだけの基礎が足りん。でも気にするな、わしの弟子のRotgathと話してみろ。あいつが手を貸してくれるさ。",
      out = "すまんな、若いの。お前にはまだ、わしが教えることを学ぶだけの基礎が足りん。でも気にするな、わしの弟子のロトガスと話してみろ。あいつが手を貸してくれるさ。" },
    { id = "gossip:9ef0022309174478:text", html = false,
      ja = "守護者たちよ！Sen'jinを守れ！",
      out = "守護者たちよ！センジンを守れ！" },
    { id = "gossip:a4b2b07cded87133:text", html = false,
      ja = "Valley of Honorへ行き、厩舎の近くにいるXon'chaを探せ。",
      out = "バレー・オブ・オナーへ行き、厩舎の近くにいるゾンチャを探せ。" },
    { id = "gossip:aa51095fae7bf95a:text", html = false,
      ja = "壊れているなら、Slagtreeが直してやるぜ！",
      out = "壊れているなら、スラグツリーが直してやるぜ！" },
    { id = "gossip:b09e2326883f388d:text", html = false,
      ja = "水のエレメンタルの中の高位の者、Hydraxisが炎の眷属と戦っているらしい。奴が負けることを願おうじゃないか！",
      out = "水のエレメンタルの中の高位の者、ハイドラクシスが炎の眷属と戦っているらしい。奴が負けることを願おうじゃないか！" },
    { id = "gossip:b61cac9e493bbf48:text", html = false,
      ja = "** 目標ロックを確認。WAR RIDER部隊、接近中。空爆まもなく。 **",
      out = "** 目標ロックを確認。ウォー・ライダー部隊、接近中。空爆まもなく。 **" },
    { id = "gossip:bbb94fd2c760ed17:text", html = false,
      ja = "Searing GorgeのSlag PitにいるDark Ironのドワーフたちは、鍵のかかった箱を大量に持っている。",
      out = "シアリング・ゴージのスラグ・ピットにいるダーク・アイアンのドワーフたちは、鍵のかかった箱を大量に持っている。" },
    { id = "gossip:c2c28cc3f5e65b30:text", html = false,
      ja = "Grimclawだと？！落ち着け、友よ……お前の主人のVolcorはどこだ？",
      out = "グリムクローだと？！落ち着け、友よ……お前の主人のヴォルコアはどこだ？" },
    { id = "gossip:c8d82dd6cfc01e9b:text", html = false,
      ja = "ああ……Ironfoeか。",
      out = "ああ……アイアンフォーか。" },
    { id = "gossip:cf86d0390c89fa61:text", html = false,
      ja = "商品を見せてほしい、Calandrath。",
      out = "商品を見せてほしい、カランドラス。" },
    { id = "gossip:d50702a3593a5c4d:text", html = false,
      ja = "Alchemy",
      out = "アルケミー" },
    { id = "gossip:db51d29cb9c8b47e:text", html = false,
      ja = "%sは目に見えて弱っている。Felcurseが効いているぞ！",
      out = "%sは目に見えて弱っている。フェルカースが効いているぞ！" },
    { id = "gossip:e11c67e3f6f5ca3c:text", html = false,
      ja = "かつてDark Ironのドワーフたちの都であったこの火山の迷宮は、今やRagnaros the Firelordの権力の座となっている。Ragnarosは石から生命を生み出す秘密を解き明かし、Blackrock Mountain全体を征服する助けとするため、止められぬゴーレムの軍勢を築こうとしている。Nefarianとその竜の手下どもを打ち倒すことに取り憑かれたRagnarosは、最後の勝利を手にするためならどんな極端な手段も厭わないだろう。",
      out = "かつてダーク・アイアンのドワーフたちの都であったこの火山の迷宮は、今やラグナロス・ザ・ファイアロードの権力の座となっている。ラグナロスは石から生命を生み出す秘密を解き明かし、ブラックロック・マウンテン全体を征服する助けとするため、止められぬゴーレムの軍勢を築こうとしている。ネファリアンとその竜の手下どもを打ち倒すことに取り憑かれたラグナロスは、最後の勝利を手にするためならどんな極端な手段も厭わないだろう。" },
    { id = "gossip:e7601752dc3822cc:text", html = false,
      ja = "やあ、{class}。このあたりのみんなと話したんだけど、Allianceが戦争に欲しがってる物は全部揃ったみたいだよ。あの怖いオークの大使によると、Hordeはまだ集めてる最中だって。だから、この荷物を全部Silithusへ送るまでにはまだ時間があるってわけ。",
      out = "やあ、{class}。このあたりのみんなと話したんだけど、アライアンスが戦争に欲しがってる物は全部揃ったみたいだよ。あの怖いオークの大使によると、ホードはまだ集めてる最中だって。だから、この荷物を全部シリサスへ送るまでにはまだ時間があるってわけ。" },
    { id = "gossip:edaf8a2a65d15f12:text", html = false,
      ja = "ごきげんよう、若き者よ。Thunder Bluffへようこそ。ここでは世の重荷から逃れ、安らかな避難所を見いだせるだろう。Hordeに属する者は皆、ここで歓迎される。\n\n友よ、この聖なる地では、今と過去の精霊たちが生き生きと蘇る。彼らを敬いなさい。そうすることで、自分自身を敬うことにもなるのだ。",
      out = "ごきげんよう、若き者よ。サンダー・ブラフへようこそ。ここでは世の重荷から逃れ、安らかな避難所を見いだせるだろう。ホードに属する者は皆、ここで歓迎される。\n\n友よ、この聖なる地では、今と過去の精霊たちが生き生きと蘇る。彼らを敬いなさい。そうすることで、自分自身を敬うことにもなるのだ。" },
    { id = "gossip:f44d3f68bdfe603d:text", html = false,
      ja = "Ragnarosの名のもとに死ね！",
      out = "ラグナロスの名のもとに死ね！" },
    { id = "gossip:fa7470b7748fc6a3:text", html = false,
      ja = "Winterspringの生き物から始めるのがいいだろうさ。\n\nだがな、他にも探せる場所があるかもしれんぞ……",
      out = "ウィンタースプリングの生き物から始めるのがいいだろうさ。\n\nだがな、他にも探せる場所があるかもしれんぞ……" },
    { id = "item:10301:description", html = false,
