    { id = "objective:479620:text", html = false,
      ja = "習得：Journeyman Riding",
      out = "習得：ジャーニーマン・ライディング" },
    { id = "quest:1032:description", html = false,
      ja = "Aniliaがいなくなったなんて信じられない……私たち、いつも森で一緒に遊んでいたのに。なんだか……悲しい気持ち。\n\n気が晴れるかもしれないことを知ってるの。お願い、私からAniliaを奪ったsatyrsを倒して！ その証として彼らの角を持ってきてくれたら、ずっと感謝するわ。",
      out = "アニリアがいなくなったなんて信じられない……私たち、いつも森で一緒に遊んでいたのに。なんだか……悲しい気持ち。\n\n気が晴れるかもしれないことを知ってるの。お願い、私からアニリアを奪ったサテュロスを倒して！ その証として彼らの角を持ってきてくれたら、ずっと感謝するわ。" },
    { id = "quest:1065:objectives", html = false,
      ja = "Zamah's NoteをTarren MillのApothecary Lydonに渡して下さい。",
      out = "ザマーズ・ノートをターレン・ミルのアポセカリー・ライドンに渡して下さい。" },
    { id = "quest:1101:title", html = false,
      ja = "Kraulの老婆",
      out = "クラウルの老婆" },
    { id = "quest:1138:completion", html = false,
      ja = "おおぅ、これはオラが欲しかったfine crab chunksでねェべか。ありがてえ、{name}！　前に、釣りしてっ時に見っけたことがあんだがな、どうにもならねェモンだったんでな。お前ならなんとかすっべがな。ありゃあどうしたって美味ェもんにはなんねェべ。\n\nカニ料理のことは話しただかな、え？",
      out = "おおぅ、これはオラが欲しかったファイン・クラブ・チャンクでねェべか。ありがてえ、{name}！　前に、釣りしてっ時に見っけたことがあんだがな、どうにもならねェモンだったんでな。お前ならなんとかすっべがな。ありゃあどうしたって美味ェもんにはなんねェべ。\n\nカニ料理のことは話しただかな、え？" },
    { id = "quest:1183:objectives", html = false,
      ja = "Fuel Regulator Blueprintsをthe Shimmering FlatsのPozzikに届けて下さい。",
      out = "フューエル・レギュレーター・ブループリントをシマリング・フラットのポジックに届けて下さい。" },
    { id = "quest:1243:progress", html = false,
      ja = "森の中をうろつくのはあまり安全じゃないぞ、{name}。気をつけて、何か怪しいものや危ないものを見かけたら、すぐにWatchersに知らせるんだ。自分で片付けようとするなよ。お前の身に何か恐ろしいことが起きても、こっちは責任を持てないからな。\n\nでもまあ、お前はどうせ俺の言うことなんか無視して、暗闇から出てくるものと片っ端から戦うんだろう? ハハ、そうさ、冒険者って連中は……みんな同じだ。",
      out = "森の中をうろつくのはあまり安全じゃないぞ、{name}。気をつけて、何か怪しいものや危ないものを見かけたら、すぐにウォッチャーに知らせるんだ。自分で片付けようとするなよ。お前の身に何か恐ろしいことが起きても、こっちは責任を持てないからな。\n\nでもまあ、お前はどうせ俺の言うことなんか無視して、暗闇から出てくるものと片っ端から戦うんだろう? ハハ、そうさ、冒険者って連中は……みんな同じだ。" },
    { id = "quest:1301:objectives", html = false,
      ja = "Menethil HarborのVincent Hyalと話して下さい。",
      out = "メネシル・ハーバーのヴィンセント・ハイアルと話して下さい。" },
    { id = "quest:1381:progress", html = false,
      ja = "俺の頼みを果たせ。Magramの味方だと証明しろ！",
      out = "俺の頼みを果たせ。マグラムの味方だと証明しろ！" },
    { id = "quest:1436:objectives", html = false,
      ja = "Orgrimmar の Keldran に話しかけてください。",
      out = "オーグリマー の ケルドラン に話しかけてください。" },
    { id = "quest:1473:description", html = false,
      ja = "皆の意見では、お前はvoidwalkerの召喚を学ぶ準備ができているようだ。\n\n彼方に広がる混沌から生まれた存在だ。召喚しても制御できなければ、お前は引き裂かれるだろう。\n\n最初のvoidwalkerはEgalinによって召喚された。そして、その手順は彼の魔導書に記されている。\n\nあいにく、それはScarlet Crusadeの手先に盗まれてしまった。そいつは西にある塔の拠点に、それを隠し持っている。それを私のところへ持ってくれば、その知識をお前に授けよう。",
      out = "皆の意見では、お前はヴォイドウォーカーの召喚を学ぶ準備ができているようだ。\n\n彼方に広がる混沌から生まれた存在だ。召喚しても制御できなければ、お前は引き裂かれるだろう。\n\n最初のヴォイドウォーカーはエガリンによって召喚された。そして、その手順は彼の魔導書に記されている。\n\nあいにく、それはスカーレット・クルセードの手先に盗まれてしまった。そいつは西にある塔の拠点に、それを隠し持っている。それを私のところへ持ってくれば、その知識をお前に授けよう。" },
    { id = "quest:1512:completion", html = false,
      ja = "{name}、これで条件を満たすと言うのなら、信じよう。だが綺麗にさせてくれ……元通りぴかぴかに。succubusにはより魅力的かもしれんのでな。",
      out = "{name}、これで条件を満たすと言うのなら、信じよう。だが綺麗にさせてくれ……元通りぴかぴかに。サキュバスにはより魅力的かもしれんのでな。" },
    { id = "quest:1618:completion", html = false,
      ja = "ありがとう、{name}。大いに助かるよ。Blackrock族オークはStonewatch Keepから攻撃を仕掛けてくるし、Redridge gnollsは北の山麓に待ち伏せしている。俺はいつも我が軍のために鎧を修理して新しい武器を作ってるんだ。\n\nあんたの持ってきてくれた物資が束の間の平穏をもたらしてくれるだろう。何かを教えてあげる時間は充分ありそうだ……。",
      out = "ありがとう、{name}。大いに助かるよ。ブラックロック族オークはストーンウォッチ・キープから攻撃を仕掛けてくるし、レッドリッジ・ノールは北の山麓に待ち伏せしている。俺はいつも我が軍のために鎧を修理して新しい武器を作ってるんだ。\n\nあんたの持ってきてくれた物資が束の間の平穏をもたらしてくれるだろう。何かを教えてあげる時間は充分ありそうだ……。" },
    { id = "quest:1684:title", html = false,
      ja = "Elanaria",
      out = "エラナリア" },
    { id = "quest:1740:title", html = false,
      ja = "Orb of Soran'ruk",
      out = "オーブ・オブ・ソランルク" },
    { id = "quest:1821:description", html = false,
      ja = "Agamand家は、私が生きていた頃の雇い主で、私の死の原因でもある！ Agamandsが今やLich Kingの心なき手先になっているのは、ふさわしい報いだ。\n\n今度は、奴らに残った名誉の最後のかけらをいただくとしよう。奴らの一族の地下墓所に入り、家宝を奪ってこい。sword、axe、短剣、そしてmaceだ。それを私のところへ持ってこい！\n\nAgamand家の地下墓所はAgamand millsの北の端にあり、潜むscourgeと死んだAgamandsに守られている。",
      out = "アガマンド家は、私が生きていた頃の雇い主で、私の死の原因でもある！ アガマンドが今やリッチ・キングの心なき手先になっているのは、ふさわしい報いだ。\n\n今度は、奴らに残った名誉の最後のかけらをいただくとしよう。奴らの一族の地下墓所に入り、家宝を奪ってこい。ソード、アックス、短剣、そしてメイスだ。それを私のところへ持ってこい！\n\nアガマンド家の地下墓所はアガマンド・ミルズの北の端にあり、潜むスコージと死んだアガマンドに守られている。" },
    { id = "quest:192:description", html = false,
      ja = "さあ、ここからが難しいところだ。本物の豹ハンターなら、Stranglethornで最も危険なShadowmaw Pantherを仕留めて腕を示せる。こいつらを10頭倒せることを証明してみせてくれ。\n\n追跡が難しいと思うなら、一頭仕留めようとしてみるまで待つんだな……",
      out = "さあ、ここからが難しいところだ。本物の豹ハンターなら、ストラングルソーンで最も危険なシャドウモー・パンサーを仕留めて腕を示せる。こいつらを10頭倒せることを証明してみせてくれ。\n\n追跡が難しいと思うなら、一頭仕留めようとしてみるまで待つんだな……" },
    { id = "quest:203:completion", html = false,
      ja = "よくやった。あのJungle Fightersがいなくなれば、野営地への圧力も多少は和らぐだろう。\n\nだが、我々が相手にしている勢力を味わった今でも、まだ我々と運命を共にするつもりか??",
      out = "よくやった。あのジャングル・ファイターがいなくなれば、野営地への圧力も多少は和らぐだろう。\n\nだが、我々が相手にしている勢力を味わった今でも、まだ我々と運命を共にするつもりか??" },
    { id = "quest:220:objectives", html = false,
      ja = "Vial of Purest WaterをBarrensにいるIslen Waterseerのところへ持って行って下さい。",
      out = "ヴァイアル・オブ・ピュアレスト・ウォーターをバレンズにいるアイスレン・ウォーターシーアのところへ持って行って下さい。" },
    { id = "quest:2359:completion", html = false,
      ja = "これで、お前とKearnenが塔の外で見たDefiasの手下どもの説明がつくな、{name}。Venture CompanyがDefiasと関わっていることや、Duskwoodから出ていく妙な荷の説明にもなる。\n\nこの本によれば、StranglethornのZanzilのトロールたちは、薬によって死者を蘇らせる方法を見つけたらしい……いや、正確に言えば毒によってだ。\n\n毒をしっかり理解していなければ、お前はSI:7の役には立たん、{name}。不死を生み出す製法が我々の手の届くところにあるならなおさらだ。",
      out = "これで、お前とカーネンが塔の外で見たデファイアスの手下どもの説明がつくな、{name}。ベンチャー・カンパニーがデファイアスと関わっていることや、ダスクウッドから出ていく妙な荷の説明にもなる。\n\nこの本によれば、ストラングルソーンのザンジルのトロールたちは、薬によって死者を蘇らせる方法を見つけたらしい……いや、正確に言えば毒によってだ。\n\n毒をしっかり理解していなければ、お前はエスアイ:7の役には立たん、{name}。不死を生み出す製法が我々の手の届くところにあるならなおさらだ。" },
    { id = "quest:2519:title", html = false,
      ja = "Temple of the Moon",
      out = "テンプル・オブ・ザ・ムーン" },
    { id = "quest:268:title", html = false,
      ja = "Svenのもとへ",
      out = "スヴェンのもとへ" },
    { id = "quest:2773:objectives", html = false,
      ja = "Trenton LighthammerにHeavy Mithril Breastplate 2つとOrnate Mithril Gloves 1つを渡して下さい。",
      out = "トレントン・ライトハンマーにヘヴィー・ミスリル・ブレストプレート 2つとオーネイト・ミスリル・グローブ 1つを渡して下さい。" },
    { id = "quest:2863:description", html = false,
      ja = "計画はこうだ。gnollsの様々な指導者――奴らはAlphasと名乗っている――を立て続けに倒す。このような素早く正確な壊滅的打撃を与えられれば、奴らの隊列に混乱を引き起こせるだろう。そしておそらく、我々は奴らを滅ぼせるし、実際に滅ぼすのだということを、蚤だらけの鈍い頭にも叩き込めるはずだ！\n\n君には我が意志を伝える使者になってもらいたい。これを成功させるには、1時間以内に奴らのAlphasを5体倒すのだ、{name}。さもなければ、我々はこの膠着状態のままだ！",
      out = "計画はこうだ。ノールの様々な指導者――奴らはアルファと名乗っている――を立て続けに倒す。このような素早く正確な壊滅的打撃を与えられれば、奴らの隊列に混乱を引き起こせるだろう。そしておそらく、我々は奴らを滅ぼせるし、実際に滅ぼすのだということを、蚤だらけの鈍い頭にも叩き込めるはずだ！\n\n君には我が意志を伝える使者になってもらいたい。これを成功させるには、1時間以内に奴らのアルファを5体倒すのだ、{name}。さもなければ、我々はこの膠着状態のままだ！" },
    { id = "quest:2931:completion", html = false,
      ja = "わしはGnomereganにおけるデータ抽出作戦を計画しておる。そのためにここへ来たんなら、よく聞け!",
      out = "わしはノームリガンにおけるデータ抽出作戦を計画しておる。そのためにここへ来たんなら、よく聞け!" },
    { id = "quest:2974:progress", html = false,
      ja = "私の言葉を真剣に受け止めろ、{class}。Grimtotem氏族は邪悪だ。奴らの居場所を突き止めたのなら、戻って奴らの氏族に最初の一撃を加えるのは君の役目だ……奴らが我々の土地に入り込み、我々の村を焼き払ったり、我々の土地を略奪したりする前にな。",
      out = "私の言葉を真剣に受け止めろ、{class}。グリムトーテム氏族は邪悪だ。奴らの居場所を突き止めたのなら、戻って奴らの氏族に最初の一撃を加えるのは君の役目だ……奴らが我々の土地に入り込み、我々の村を焼き払ったり、我々の土地を略奪したりする前にな。" },
    { id = "quest:3042:title", html = false,
      ja = "Troll Temper",
      out = "トロール・テンパー" },
    { id = "quest:3106:progress", html = false,
      ja = "くそっ、今日は寒いな? 雪がまるで消えやしないみたいだ、{name}。\n\nもう気づいてるだろうが、今この街にはノームが住んでる。自分たちの故郷から吹っ飛ばされちまったからさ。言いふらすんじゃないぞ、だが奴らを責める気にはなれん……IronforgeがDark Ironsなんかに荒らされたら、俺だって爆薬に頼っただろうからな。",
      out = "くそっ、今日は寒いな? 雪がまるで消えやしないみたいだ、{name}。\n\nもう気づいてるだろうが、今この街にはノームが住んでる。自分たちの故郷から吹っ飛ばされちまったからさ。言いふらすんじゃないぞ、だが奴らを責める気にはなれん……アイアンフォージがダーク・アイアンなんかに荒らされたら、俺だって爆薬に頼っただろうからな。" },
    { id = "quest:319:objectives", html = false,
      ja = "Ice Claw Bearを6匹、Elder Crag BoarとSnow Leopardを8匹ずつ殺したら、Brewnall VillageにいるRejold Barleybrewに報告に戻れ。",
      out = "アイス・クロー・ベアを6匹、エルダー・クラッグ・ボアとスノー・レパードを8匹ずつ殺したら、ブルーノール・ヴィレッジにいるレジョルド・バーリーブルーに報告に戻れ。" },
    { id = "quest:3377:objectives", html = false,
      ja = "Zamaelが語る話を聞いて下さい。",
      out = "ザマエルが語る話を聞いて下さい。" },
    { id = "quest:3502:description", html = false,
      ja = "さて、あの貪欲さを見せつけられて、吐き気がしてきました。\n\nともあれ、あなたの物欲についてあまり長く考えるつもりはありません。\n\n不完全なdraenethystの欠片を渡してくれるたびに、ガラクタを報酬として差し上げましょう。私のガラクタの山は小さくなり、あなたのガラクタの山は大きくなる。Draenorでは、これを「ウィンウィン」の状況と呼ぶのです。",
      out = "さて、あの貪欲さを見せつけられて、吐き気がしてきました。\n\nともあれ、あなたの物欲についてあまり長く考えるつもりはありません。\n\n不完全なドレネシストの欠片を渡してくれるたびに、ガラクタを報酬として差し上げましょう。私のガラクタの山は小さくなり、あなたのガラクタの山は大きくなる。ドレナーでは、これを「ウィンウィン」の状況と呼ぶのです。" },
    { id = "quest:3566:title", html = false,
      ja = "蘇れ、Obsidion！",
      out = "蘇れ、オブシディオン！" },
    { id = "quest:367:objectives", html = false,
      ja = "Brillの町にいるApothecary JohaanはVial of Darkhound Bloodを５つ求めています。",
      out = "ブリルの町にいるアポセカリー・ヨハーンはヴァイアル・オブ・ダークハウンド・ブラッドを５つ求めています。" },
    { id = "quest:3802:objectives", html = false,
      ja = "Fineous Darkvireを討ち取り、大いなるハンマーIronfelを取り戻して下さい。IronfelをShrine of Thaurissanへ持って行き、Franclorn Forgewrightの石像に安置して下さい。",
      out = "フィネアス・ダークヴァイアを討ち取り、大いなるハンマーアイアンフェルを取り戻して下さい。アイアンフェルをシュライン・オブ・ソーリサンへ持って行き、フランクローン・フォージライトの石像に安置して下さい。" },
    { id = "quest:391:objectives", html = false,
      ja = "Bazil Threddを殺し、その首をStockadeのWarden Thelwaterに渡して下さい。",
      out = "バジル・スレッドを殺し、その首をストッケードのウォーデン・セルウォーターに渡して下さい。" },
    { id = "quest:408:objectives", html = false,
      ja = "Wailing Ancestor８匹とRotting Ancestor８匹を倒してください。\n\nCaptain Dargolを倒して、彼の頭蓋骨をBrillにいるMagistrate Sevrenに渡してください。",
      out = "ウェイリング・アンセスター８匹とロッティング・アンセスター８匹を倒してください。\n\nキャプテン・ダーゴルを倒して、彼の頭蓋骨をブリルにいるマジストレート・セヴレンに渡してください。" },
    { id = "quest:4136:title", html = false,
      ja = "Ribbly Screwspigot",
      out = "リブリー・スクリュースピゴット" },
    { id = "quest:4261:objectives", html = false,
      ja = "Areiを安全な場所まで護衛し、Ashenvale東部のForest SongにいるKayneth Stillwindと話して下さい。",
      out = "アレイを安全な場所まで護衛し、アッシェンヴェイル東部のフォレスト・ソングにいるケイネス・スティルウィンドと話して下さい。" },
    { id = "quest:4362:description", html = false,
      ja = "どうやらわしの宿敵、Dagran Thaurissanは、わしとIronforgeの王国を思いのままにしておるようだ。\n\nそなたがわしの最後の希望かもしれん、{name}。わしの愛しい娘、Moiraを救い出してくれ!\n\nThaurissanがMoiraにかけた呪文を確実に解く方法はただ一つ。奴を殺すことだ。\n\nそれから{name}、娘を傷つけてはならんぞ! 忘れるな、娘はThaurissanに操られておるのだ! 娘が何をしようと、何を言おうと、それはThaurissanの邪悪な呪文のせいなのだ!",
      out = "どうやらわしの宿敵、ダグラン・ソーリサンは、わしとアイアンフォージの王国を思いのままにしておるようだ。\n\nそなたがわしの最後の希望かもしれん、{name}。わしの愛しい娘、モイラを救い出してくれ!\n\nソーリサンがモイラにかけた呪文を確実に解く方法はただ一つ。奴を殺すことだ。\n\nそれから{name}、娘を傷つけてはならんぞ! 忘れるな、娘はソーリサンに操られておるのだ! 娘が何をしようと、何を言おうと、それはソーリサンの邪悪な呪文のせいなのだ!" },
    { id = "quest:4486:description", html = false,
      ja = "おやおや、威風堂々たる強大なパラディン様のお出ましだ。\n\n悪い、{name}、気を悪くさせるつもりはなかったんだ……君が成し遂げた偉業を見ると、ときどきちょっと妬ましくなってね。Tizaにはそれが僕の弱さだって言われて、直すって彼女に誓ったんだ。でも、ときどき難しいんだよ、分かるだろ？\n\nでも、君と話したかったのは、StormwindのDuthorian Rallから、準備ができたらCathedral of Lightで会いたいと君に伝言が届いたからなんだ。大事な話みたいだったよ。何かが起きているみたいだった。",
      out = "おやおや、威風堂々たる強大なパラディン様のお出ましだ。\n\n悪い、{name}、気を悪くさせるつもりはなかったんだ……君が成し遂げた偉業を見ると、ときどきちょっと妬ましくなってね。ティザにはそれが僕の弱さだって言われて、直すって彼女に誓ったんだ。でも、ときどき難しいんだよ、分かるだろ？\n\nでも、君と話したかったのは、ストームウィンドのデュソリアン・ラルから、準備ができたらカテドラル・オブ・ライトで会いたいと君に伝言が届いたからなんだ。大事な話みたいだったよ。何かが起きているみたいだった。" },
    { id = "quest:45:completion", html = false,
      ja = "「Footman Rolf Hartford」と刻まれている金属製のメダルを首につけた遺体を発見した。",
      out = "「フットマン・ロルフ・ハートフォード」と刻まれている金属製のメダルを首につけた遺体を発見した。" },
    { id = "quest:4736:description", html = false,
      ja = "ああ、やあ、{name}。訓練は順調に進んでいるな。あまりに順調だから、その努力に――それと、まだ秘術に堕落していないことに――報いるべきだと思うのだ。\n\n興味があるなら、RatchetのMenara Voidrenderを訪ねるといい。彼女は今、町を見下ろすStrahad Farsanの塔に滞在している。\n\nあまり愛想のいい女ではないぞ、{name}。褒め言葉は期待するな。だが一生懸命やれば、面倒は見てくれるだろう。",
      out = "ああ、やあ、{name}。訓練は順調に進んでいるな。あまりに順調だから、その努力に――それと、まだ秘術に堕落していないことに――報いるべきだと思うのだ。\n\n興味があるなら、ラチェットのメナラ・ヴォイドレンダーを訪ねるといい。彼女は今、町を見下ろすストラハド・ファーサンの塔に滞在している。\n\nあまり愛想のいい女ではないぞ、{name}。褒め言葉は期待するな。だが一生懸命やれば、面倒は見てくれるだろう。" },
    { id = "quest:4804:completion", html = false,
      ja = "Mau'ariが{name}のために呪力を引き出してやれるぜ……Cache of Mau'ariを使って、お前自身か仲間にこいつをかけるんだ。",
      out = "マウアリが{name}のために呪力を引き出してやれるぜ……キャッシュ・オブ・マウアリを使って、お前自身か仲間にこいつをかけるんだ。" },
    { id = "quest:490:description", html = false,
      ja = "Sentinelsの厳命により、私はGnarlpineに懸賞金をかけています。彼らはもはや森の友ではありません。堕落によって心を失い、我々の民と森の空き地の生き物たちを脅かす存在となってしまったのです。\n\n定められた通り、Teldrassilからfurbolgの脅威を取り除いた者には報酬が与えられます。その働きの証として、彼らのGnarlpine Fangを持ってきてください。\n\nfurbolgは、Dolanaarの西、道の南にあるBan'ethil Hollowと、東のStarbreeze Villageに集まっています。",
      out = "センチネルの厳命により、私はナールパインに懸賞金をかけています。彼らはもはや森の友ではありません。堕落によって心を失い、我々の民と森の空き地の生き物たちを脅かす存在となってしまったのです。\n\n定められた通り、テルドラシルからファーボルグの脅威を取り除いた者には報酬が与えられます。その働きの証として、彼らのナールパイン・ファングを持ってきてください。\n\nファーボルグは、ドラナールの西、道の南にあるバネシル・ホロウと、東のスターブリーズ・ヴィレッジに集まっています。" },
    { id = "quest:5022:progress", html = false,
      ja = "Stormwind国勢調査局へようこそ。住民に関する情報が必要でしたら、お手伝いいたします。",
      out = "ストームウィンド国勢調査局へようこそ。住民に関する情報が必要でしたら、お手伝いいたします。" },
    { id = "quest:508:title", html = false,
      ja = "Tarethaの贈り物",
      out = "タレサの贈り物" },
    { id = "quest:5154:description", html = false,
      ja = "Joseph Redpathを救うには、まず彼の過去を知らなければならないわ。それはAndorhalの町役場に保管されている本、Annals of Darrowshireで知ることができるの。\n\nその本を持ってきて。そうすればJosephの運命を知ることができるし、運が良ければ……それを変えられるわ！",
      out = "ジョセフ・レッドパスを救うには、まず彼の過去を知らなければならないわ。それはアンドーハルの町役場に保管されている本、アナールズ・オブ・ダロウシャーで知ることができるの。\n\nその本を持ってきて。そうすればジョセフの運命を知ることができるし、運が良ければ……それを変えられるわ！" },
    { id = "quest:521:title", html = false,
      ja = "Crown of Will",
      out = "クラウン・オブ・ウィル" },
    { id = "quest:5264:title", html = false,
      ja = "Lord Maxwell Tyrosus",
      out = "ロード・マクスウェル・ティロサス" },
    { id = "quest:5405:title", html = false,
      ja = "Argent Dawn Commission",
      out = "アージェント・ドーン・コミッション" },
    { id = "quest:5517:objectives", html = false,
      ja = "Argent Dawn Valor Tokensを$N1個、Eastern PlaguelandsのLight's Hope ChapelにいるQuartermaster Breechlockのところへ持って行って下さい。",
      out = "アージェント・ドーン・ヴァラー・トークンを$N1個、イースタン・プレイグランドのライツ・ホープ・チャペルにいるクオーターマスター・ブリーチロックのところへ持って行って下さい。" },
    { id = "quest:5601:completion", html = false,
      ja = "私のお姉ちゃんのJessicaはどこ? ずっと前、私がまだ小さな女の子だったときに行っちゃったの。行くとき、すごく泣いてた。どうして泣いてたのか分からない! 転んでつま先をぶつけたのかも。\n\nJessicaがここにいたときは、一緒に遊んだり踊ったり、家のまわりできれいなお花を摘んだりしてたの。それに、パパが帰ってくるのが見えたら隠れて、飛び出してびっくりさせたりもしたんだ!\n\n帰ってきて、Jessica! お姉ちゃんが帰ってきたら、パパもきっと帰ってきて、またみんなで一緒に遊べるかもしれないのに……",
      out = "私のお姉ちゃんのジェシカはどこ? ずっと前、私がまだ小さな女の子だったときに行っちゃったの。行くとき、すごく泣いてた。どうして泣いてたのか分からない! 転んでつま先をぶつけたのかも。\n\nジェシカがここにいたときは、一緒に遊んだり踊ったり、家のまわりできれいなお花を摘んだりしてたの。それに、パパが帰ってくるのが見えたら隠れて、飛び出してびっくりさせたりもしたんだ!\n\n帰ってきて、ジェシカ! お姉ちゃんが帰ってきたら、パパもきっと帰ってきて、またみんなで一緒に遊べるかもしれないのに……" },
    { id = "quest:5662:objectives", html = false,
      ja = "UndercityのAelthalysteと話す。",
      out = "アンダーシティのエルサリストと話す。" },
    { id = "quest:5801:description", html = false,
      ja = "鍵の軸を鍛えるには、thoriumの延べ棒が二本と、ものすごく熱い熱源が必要だ。thoriumは自分でなんとかしてもらうしかないが、熱のほうは手を貸せる。\n\nここから西のUn'Goro CraterにFire Plume Ridgeがある――ぐつぐつ煮えたぎる火山だ。頂上の溶岩湖は、thoriumと骨を溶かし合わせるのに十分な熱さだ。君の金で手に入れたこの鋳型は、頂上の湖に浸すだけでいい。あとは溶岩がやってくれる。\n\nこっちでできるのはここまでだ。鍵を仕上げるには、もう一度Arbingtonと話す必要がある。",
      out = "鍵の軸を鍛えるには、ソーリウムの延べ棒が二本と、ものすごく熱い熱源が必要だ。ソーリウムは自分でなんとかしてもらうしかないが、熱のほうは手を貸せる。\n\nここから西のウンゴロ・クレーターにファイア・プルーム・リッジがある――ぐつぐつ煮えたぎる火山だ。頂上の溶岩湖は、ソーリウムと骨を溶かし合わせるのに十分な熱さだ。君の金で手に入れたこの鋳型は、頂上の湖に浸すだけでいい。あとは溶岩がやってくれる。\n\nこっちでできるのはここまでだ。鍵を仕上げるには、もう一度アービントンと話す必要がある。" },
    { id = "quest:589:objectives", html = false,
      ja = "３個のPulsing Blue ShardsをGrom'gol Base CampのKin'weelayに届けてください。",
      out = "３個のパルシング・ブルー・シャードをグロムゴル・ベース・キャンプのキンウィーレイに届けてください。" },
    { id = "quest:601:title", html = false,
      ja = "Water Elementals",
      out = "ウォーター・エレメンタル" },
    { id = "quest:608:completion", html = false,
      ja = "ああ、なんてBlackwater Raidersにとって素晴らしい日なんだ！　{name}に、万歳三唱！",
      out = "ああ、なんてブラックウォーター・レイダーにとって素晴らしい日なんだ！　{name}に、万歳三唱！" },
    { id = "quest:6182:completion", html = false,
      ja = "Eastern PlaguelandsでForsakenの不審な動きが報告されたのを受けて、SI:7の工作員が調査に派遣された。その調査結果は不穏なものだ。",
      out = "イースタン・プレイグランドでフォーセイクンの不審な動きが報告されたのを受けて、エスアイ:7の工作員が調査に派遣された。その調査結果は不穏なものだ。" },
    { id = "quest:6343:objectives", html = false,
      ja = "Laird's ResponseをNessa Shadowsongのところへ持って行って下さい。",
      out = "レアードズ・レスポンスをネッサ・シャドウソングのところへ持って行って下さい。" },
    { id = "quest:643:title", html = false,
      ja = "Sigil of Arathor",
      out = "シジル・オブ・アラソール" },
    { id = "quest:65604:description", html = false,
      ja = "そうか……分かったぞ。この糸に込められた感情の名残を感じる。その縫い目には愛が織り込まれている。incubusは抗えまい。\n\nこれをNeeruのテントにある召喚の円へ持っていけ、{name}。悪意あるincubusを呼び出し、お前の腕前を見せつけてやれ。大人しく屈服するとは思うな。魔法を用意し、戦いに備えろ。悪魔を侮ったことが、多くのウォーロックにとって最後の過ちとなってきたのだ。\n\nそいつを倒したら、その布を私に返せ。お前が見つけたことはMagarに伝えておこう。",
      out = "そうか……分かったぞ。この糸に込められた感情の名残を感じる。その縫い目には愛が織り込まれている。インキュバスは抗えまい。\n\nこれをニーエルのテントにある召喚の円へ持っていけ、{name}。悪意あるインキュバスを呼び出し、お前の腕前を見せつけてやれ。大人しく屈服するとは思うな。魔法を用意し、戦いに備えろ。悪魔を侮ったことが、多くのウォーロックにとって最後の過ちとなってきたのだ。\n\nそいつを倒したら、その布を私に返せ。お前が見つけたことはマガーに伝えておこう。" },
    { id = "quest:6629:completion", html = false,
      ja = "Grundig Darkcloudが死んだ！　{name}、あなたが今日ここでしてくださったことは、一生忘れません。",
      out = "グランディグ・ダーククラウドが死んだ！　{name}、あなたが今日ここでしてくださったことは、一生忘れません。" },
    { id = "quest:6827:progress", html = false,
      ja = "何日もドワーフのひどい牢獄に閉じ込められていたんだ。復讐したいに決まってるだろう！\n\n慎重に計画を立てねばならん。\n\nまず、俺のwar ridersには狙うべき標的が必要だ。最優先の標的がな。奴らにはStormpike Commandersの肉を食わせてやるつもりだ。あいにく、あのちびどもは敵陣の奥深くに立てこもっている！お前の仕事は間違いなく骨が折れるぞ。",
      out = "何日もドワーフのひどい牢獄に閉じ込められていたんだ。復讐したいに決まってるだろう！\n\n慎重に計画を立てねばならん。\n\nまず、俺のウォー・ライダーには狙うべき標的が必要だ。最優先の標的がな。奴らにはストームパイク・コマンダーの肉を食わせてやるつもりだ。あいにく、あのちびどもは敵陣の奥深くに立てこもっている！お前の仕事は間違いなく骨が折れるぞ。" },
    { id = "quest:6985:progress", html = false,
      ja = "Irondeep mineには入ったか、{name}？そこのsuppliesを奪ってきたか？",
      out = "アイアンディープ・マインには入ったか、{name}？そこのサプライを奪ってきたか？" },
    { id = "quest:707:description", html = false,
      ja = "{name}。Loch Modanの発掘現場にいるProspector Ironbandから報告を受けた。我々の別の発掘作業について、足を使った仕事をしてくれる者が必要だそうだ。\n\nそれ以上の詳細は分からないが、足を伸ばしてみたいなら、Ironbandと話しに行ってくれ。",
      out = "{name}。ロッホ・モダンの発掘現場にいるプロスペクター・アイアンバンドから報告を受けた。我々の別の発掘作業について、足を使った仕事をしてくれる者が必要だそうだ。\n\nそれ以上の詳細は分からないが、足を伸ばしてみたいなら、アイアンバンドと話しに行ってくれ。" },
    { id = "quest:7241:title", html = false,
      ja = "Frostwolfを守るために",
      out = "フロストウルフを守るために" },
    { id = "quest:7481:description", html = false,
      ja = "数年前、Telmius Dreamseekerという孤高のエルフの師が、いくつかの古代エルフの遺物を携えて、荒廃した故郷から逃れました。\n\nこの失われた師を探す私たちの旅は、Quel'Thalasの廃墟からBurning Steppesを抜け、広大な海を渡り、Feralasへと至りました。\n\n私たちは、そのエルフがEldre'Thalas（今ではDire Maulと呼ばれる場所）の広間に避難したのではないかと考えています。\n\n彼を見つけてください、冒険者よ。生きていようと死んでいようと、彼が携えていた知識は取り戻さねばならないのです！",
      out = "数年前、テルミウス・ドリームシーカーという孤高のエルフの師が、いくつかの古代エルフの遺物を携えて、荒廃した故郷から逃れました。\n\nこの失われた師を探す私たちの旅は、ケルサラスの廃墟からバーニング・ステップを抜け、広大な海を渡り、フェララスへと至りました。\n\n私たちは、そのエルフがエルドレサラス（今ではダイア・モールと呼ばれる場所）の広間に避難したのではないかと考えています。\n\n彼を見つけてください、冒険者よ。生きていようと死んでいようと、彼が携えていた知識は取り戻さねばならないのです！" },
    { id = "quest:7582:description", html = false,
      ja = "Mount Hyjalの麓に巣食うHederineの悪魔どもは、強力な邪悪の毒を分泌する。それが熟すと、魔法を寄せつけない密な水晶へと固まるのだ。この水晶はTears of the Hederineとして知られるようになった。\n\nこの素材で作られた牢獄の壁は、Doomguardの途方もない力をもってしても破れはしない。\n\nWinterspringのDarkwhisper Gorgeへ赴き、Tearsを取り戻してこい。",
      out = "マウント・ハイジャルの麓に巣食うヘデリンの悪魔どもは、強力な邪悪の毒を分泌する。それが熟すと、魔法を寄せつけない密な水晶へと固まるのだ。この水晶はティア・オブ・ザ・ヘデリンとして知られるようになった。\n\nこの素材で作られた牢獄の壁は、ドゥームガードの途方もない力をもってしても破れはしない。\n\nウィンタースプリングのダークウィスパー・ゴージへ赴き、ティアを取り戻してこい。" },
    { id = "quest:7644:progress", html = false,
      ja = "{name}、戻ったのね！ Merideth CarlsonとTendris Warpwoodの件はうまく片付けられた？ 正直なところ、時々どちらがより大きな脅威なのか分からなくなるわ……",
      out = "{name}、戻ったのね！ メレディス・カールソンとテンドリス・ワープウッドの件はうまく片付けられた？ 正直なところ、時々どちらがより大きな脅威なのか分からなくなるわ……" },
    { id = "quest:7733:description", html = false,
      ja = "もっと良いhidesの出どころの手がかりをつかんだんだ。信じられないかもしれないけどな！Feralasの北部――Rage Scar Holdの奥深くに、また別のyetisの群れがいるんだ。前にお前が相手にした奴らよりずっと手強いから、もっと大きな挑戦をする気があるなら、せいぜい油断しないことだな！\n\n奴らのhidesを10枚ひと束持ってきてくれたら、たっぷり礼をするよ。ここへ持ってきてくれ、それで取引は完了だ。",
      out = "もっと良いハイドの出どころの手がかりをつかんだんだ。信じられないかもしれないけどな！フェララスの北部――レイジ・スカー・ホールドの奥深くに、また別のイェティの群れがいるんだ。前にお前が相手にした奴らよりずっと手強いから、もっと大きな挑戦をする気があるなら、せいぜい油断しないことだな！\n\n奴らのハイドを10枚ひと束持ってきてくれたら、たっぷり礼をするよ。ここへ持ってきてくれ、それで取引は完了だ。" },
    { id = "quest:7813:progress", html = false,
      ja = "現在、wool clothの寄付を受け付けています。wool cloth60枚を寄付していただければ、その寛大な行いがUndercityに十分に認められるでしょう。woolの蓄えの状況からすると、あなたからいただくのは合計60枚だけで済みます。残りはこの世界の他の方々から集めて、この運動を支えられるはずです。\n\nwool cloth60枚をお持ちで寄付の準備ができているなら、今すぐお預かりできますよ。",
      out = "現在、ウール・クロスの寄付を受け付けています。ウール・クロス60枚を寄付していただければ、その寛大な行いがアンダーシティに十分に認められるでしょう。ウールの蓄えの状況からすると、あなたからいただくのは合計60枚だけで済みます。残りはこの世界の他の方々から集めて、この運動を支えられるはずです。\n\nウール・クロス60枚をお持ちで寄付の準備ができているなら、今すぐお預かりできますよ。" },
    { id = "quest:7862:title", html = false,
      ja = "求人：Revantusk Villageの衛兵隊長",
      out = "求人：レヴァンタスク・ヴィレッジの衛兵隊長" },
    { id = "quest:791:completion", html = false,
      ja = "実にいいね、{name}。あらゆる本物の{class}は戦場でのこのバッグの使い方を知ってるものさ。\n\nHordeの名の下に戦わんとするお前の意志に敬礼！",
      out = "実にいいね、{name}。あらゆる本物の{class}は戦場でのこのバッグの使い方を知ってるものさ。\n\nホードの名の下に戦わんとするお前の意志に敬礼！" },
    { id = "quest:7:title", html = false,
      ja = "Koboldキャンプの掃討",
      out = "コボルドキャンプの掃討" },
    { id = "quest:806:description", html = false,
      ja = "DurotarにBurning Bladeの橋頭堡を築かせてはならん！ひどくなる前に手を打たねばならん！\n\n調べたところBurning Bladeのウォーロック、ゴブリンのFizzle Darkstormが北西のThunder Ridgeの中で宿営していることがわかった。奴とその手下はそこから混迷を広めている。\n\nFizzleを見つけ出して、殺せ。そして彼のつめを取ってくるのだ。",
      out = "デュロターにバーニング・ブレードの橋頭堡を築かせてはならん！ひどくなる前に手を打たねばならん！\n\n調べたところバーニング・ブレードのウォーロック、ゴブリンのフィズル・ダークストームが北西のサンダー・リッジの中で宿営していることがわかった。奴とその手下はそこから混迷を広めている。\n\nフィズルを見つけ出して、殺せ。そして彼のつめを取ってくるのだ。" },
    { id = "quest:8142:title", html = false,
      ja = "Zandalarian Shadow Talisman",
      out = "ザンダラリアン・シャドウ・タリスマン" },
    { id = "quest:81746:title", html = false,
      ja = "Duskwood任務XVII：Alara Grovemender救出",
      out = "ダスクウッド任務セブンティーン：アララ・グローヴメンダー救出" },
    { id = "quest:81856:title", html = false,
      ja = "Feralas任務II：Harpies討伐",
      out = "フェララス任務ツー：ハーピー討伐" },
    { id = "quest:823:title", html = false,
      ja = "Orgnilへの報告",
      out = "オルグニルへの報告" },
    { id = "quest:828:description", html = false,
      ja = "我らシャーマンの一人、MargozはBurning Bladeの腐敗についてより多くのことを知っているだろう。彼はBurning Bladeのカルト信者の大集団が隠れているSkull Rockと呼ばれるOrgrimmarのすぐそばにある洞窟について話をしてくれるだろう。\n\nSkull Rockへ行く前にMargozと話をするといい。彼は賢明であり、彼の助言は高く評価されている。\n\n彼はここから北東の海岸とDrygulch Ravineの間で野営している。\n\n彼の助言に従え。しかしMargozがなんと言おうとも{name}、あのカルト信者どもを打ちのめしてほしい！",
      out = "我らシャーマンの一人、マーゴズはバーニング・ブレードの腐敗についてより多くのことを知っているだろう。彼はバーニング・ブレードのカルト信者の大集団が隠れているスカル・ロックと呼ばれるオーグリマーのすぐそばにある洞窟について話をしてくれるだろう。\n\nスカル・ロックへ行く前にマーゴズと話をするといい。彼は賢明であり、彼の助言は高く評価されている。\n\n彼はここから北東の海岸とドライガルチ・ラヴィーンの間で野営している。\n\n彼の助言に従え。しかしマーゴズがなんと言おうとも{name}、あのカルト信者どもを打ちのめしてほしい！" },
    { id = "quest:8351:title", html = false,
      ja = "Borが話したがっています",
      out = "ボルが話したがっています" },
    { id = "quest:8398:progress", html = false,
      ja = "Hordeとの戦争で我々の物資は急速に尽きつつある、{name}。資源の流れを絶やさぬためには、Arathi Basinの支配を保つことが何よりも重要だ! もうArathiで力を貸してくれたか?",
      out = "ホードとの戦争で我々の物資は急速に尽きつつある、{name}。資源の流れを絶やさぬためには、アラシ・ベイスンの支配を保つことが何よりも重要だ! もうアラシで力を貸してくれたか?" },
    { id = "quest:84183:description", html = false,
      ja = "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Delianaのところへ戻り、彼女に伝えてくれ。残りの破片を見つけるには、Bodleyだけが頼りだと。手筈を整えた君への報酬については、彼女と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!",
      out = "ヴァルサラクの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nヴァルサラクの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。デリアナのところへ戻り、彼女に伝えてくれ。残りの破片を見つけるには、ボドリーだけが頼りだと。手筈を整えた君への報酬については、彼女と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!" },
    { id = "quest:8436:progress", html = false,
      ja = "Arathiからの知らせを持って戻ってきたのか、{class}?",
      out = "アラシからの知らせを持って戻ってきたのか、{class}?" },
    { id = "quest:8499:title", html = false,
      ja = "AllianceはThorium Barsを必要としている！",
      out = "アライアンスはソーリウム・バーを必要としている！" },
    { id = "quest:8567:completion", html = false,
      ja = "ああ、そうだとも! Warsong Gulchでの君のこれまでの功績を、もちろん忘れたりはしないよ。",
      out = "ああ、そうだとも! ウォーソング・ガルチでの君のこれまでの功績を、もちろん忘れたりはしないよ。" },
    { id = "quest:8647:title", html = false,
      ja = "Bellowrage the Elder",
      out = "ベロウレイジ・ザ・エルダー" },
    { id = "quest:8692:description", html = false,
      ja = "Ahn'Qirajへの攻撃を支援してくれていると聞いて嬉しいよ、{name}。私なら、我々の敵との戦いの役に立つ防御用の品を作れるよ、{class}。\n\nQirajiのマントが必要だな。もちろん、君用のサイズに作り直すつもりさ。像とスカラベも要る。そっちは留め具を作るのに使うんだよ。\n\n期待は裏切らないと誓うよ。",
      out = "アンキラージへの攻撃を支援してくれていると聞いて嬉しいよ、{name}。私なら、我々の敵との戦いの役に立つ防御用の品を作れるよ、{class}。\n\nキラジのマントが必要だな。もちろん、君用のサイズに作り直すつもりさ。像とスカラベも要る。そっちは留め具を作るのに使うんだよ。\n\n期待は裏切らないと誓うよ。" },
    { id = "quest:873:objectives", html = false,
      ja = "Heart of Isha AwakをMahren Skyseerに渡して下さい。",
      out = "ハート・オブ・イシャ・アワクをマーレン・スカイシーアに渡して下さい。" },
    { id = "quest:8812:progress", html = false,
      ja = "commendation signetを1つしか持っていない冒険者のためには、それをGnomeregan Exilesでのわずかな評価と引き換えよう。\n\nただし、signetは10個ひとまとめにして一度に渡す方がよいことは覚えておいてくれ。その方がその働きはより大きく評価される。ひとまとめ分に満たない者のために、signet1個での交換も行っているというだけのことだ。\n\nとはいえ、それでもsignetを1つ渡したいというのなら、喜んで手を貸そう。",
      out = "コメンデーション・シグネットを1つしか持っていない冒険者のためには、それをノームリガン・エグザイルでのわずかな評価と引き換えよう。\n\nただし、シグネットは10個ひとまとめにして一度に渡す方がよいことは覚えておいてくれ。その方がその働きはより大きく評価される。ひとまとめ分に満たない者のために、シグネット1個での交換も行っているというだけのことだ。\n\nとはいえ、それでもシグネットを1つ渡したいというのなら、喜んで手を貸そう。" },
    { id = "quest:8870:title", html = false,
      ja = "Lunar Festival",
      out = "ルナー・フェスティバル" },
    { id = "quest:8920:objectives", html = false,
      ja = "Silithus Venom Sample15個と20GoldをBracers of Valorとセットにして、OrgrimmarのMokvarに渡して下さい。",
      out = "シリサス・ヴェノム・サンプル15個と20ゴールドをブレイサー・オブ・ヴァラーとセットにして、オーグリマーのモクヴァーに渡して下さい。" },
    { id = "quest:8964:description", html = false,
      ja = "{class}、よく聞くのだ。火鉢とそれに火を灯す手段は手に入ったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友たちの亡骸を呼び出せるほど強い、焦点となるものがな。\n\n兄弟のJarienとSothosは、Scarlet Crusadeの教えを信じていた。彼らはあの邪悪な組織の中で騎士になることを望んでいた。Eastern PlaguelandsのTyr's Handへ行き、そこにいるpraetoriansからBrilliant Sword of Zealotryを取り戻してくるのだ。",
      out = "{class}、よく聞くのだ。火鉢とそれに火を灯す手段は手に入ったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友たちの亡骸を呼び出せるほど強い、焦点となるものがな。\n\n兄弟のジャリエンとソソスは、スカーレット・クルセードの教えを信じていた。彼らはあの邪悪な組織の中で騎士になることを望んでいた。イースタン・プレイグランドのティールズ・ハンドへ行き、そこにいるプリトーリアンからブリリアント・ソード・オブ・ゼラトリーを取り戻してくるのだ。" },
    { id = "quest:9011:progress", html = false,
      ja = "取り決め通り、新しいCoif and Vest of The Five Thundersと引き換えに、お前のElementsの装備を渡す用意はできているか",
      out = "取り決め通り、新しいコイフ・アンド・ベスト・オブ・ザ・ファイブ・サンダーと引き換えに、お前のエレメントの装備を渡す用意はできているか" },
    { id = "quest:91209:objectives", html = false,
      ja = "Deathknellから東へ道をたどり、Brillの町を見つけてください。訓練を続けるため、Shari Stilwellに報告してください。",
      out = "デスネルから東へ道をたどり、ブリルの町を見つけてください。訓練を続けるため、シャリ・スティルウェルに報告してください。" },
    { id = "quest:91735:description", html = false,
      ja = "いいか、{class}、ここに長居はしないほうがいいぜ。だが、せっかくいるんなら、ちょっと頼みを聞いてくれないか？\n\n俺はAzsharaにいるJedigaから、ある物を待ってるんだ。あいつとオーク何人かがあっちでキャンプを張ってる。行って、Jes'rimonに言われて来たと伝えてくれ。そしたら、お前に一つ借りだ。",
      out = "いいか、{class}、ここに長居はしないほうがいいぜ。だが、せっかくいるんなら、ちょっと頼みを聞いてくれないか？\n\n俺はアズシャラにいるジェディガから、ある物を待ってるんだ。あいつとオーク何人かがあっちでキャンプを張ってる。行って、ジェスリモンに言われて来たと伝えてくれ。そしたら、お前に一つ借りだ。" },
    { id = "quest:91921:completion", html = false,
      ja = "<Quinnは薬を受け取って飲み干す。>\n\nああ、効いているのが分かる。すぐにまた旅ができるようになるだろう。\n\n大きな恩ができたよ、{name}。",
      out = "<クインは薬を受け取って飲み干す。>\n\nああ、効いているのが分かる。すぐにまた旅ができるようになるだろう。\n\n大きな恩ができたよ、{name}。" },
    { id = "quest:9230:description", html = false,
      ja = "この指輪を直すのはかなり骨が折れるかもしれないよ、{name}。というのも、これはScourgeの建造物――Naxxramasのような――の中で生まれるルーンそのものから作られているんだ。ほかにも材料が要るけど、一番気にかけるべきはそのfrozen runesを手に入れることさ。必要なものを持ってきてくれたら、指輪をかつての輝きに戻してあげるよ。",
      out = "この指輪を直すのはかなり骨が折れるかもしれないよ、{name}。というのも、これはスコージの建造物――ナクスラーマスのような――の中で生まれるルーンそのものから作られているんだ。ほかにも材料が要るけど、一番気にかけるべきはそのフローズン・ルーンを手に入れることさ。必要なものを持ってきてくれたら、指輪をかつての輝きに戻してあげるよ。" },
    { id = "quest:92470:completion", html = false,
      ja = "実に見事だ。君は獣を倒し、侵入してきた教団員どもを打ち倒した。大いに見込みがあるが、君の道はまもなく比較的安全なThendal Villageの外へと続かねばならない。",
      out = "実に見事だ。君は獣を倒し、侵入してきた教団員どもを打ち倒した。大いに見込みがあるが、君の道はまもなく比較的安全なセンダル・ヴィレッジの外へと続かねばならない。" },
    { id = "quest:9261:objectives", html = false,
      ja = "Ironforgeの外にいるScourgeからDim Necrotic Stoneを3個集め、彼らの野営地の近くにある光るルーンの円陣を調べてください。",
      out = "アイアンフォージの外にいるスコージからディム・ネクロティック・ストーンを3個集め、彼らの野営地の近くにある光るルーンの円陣を調べてください。" },
    { id = "quest:92814:objectives", html = false,
      ja = "Gelkisとの評判を維持し、White Bandit MaskをDesolaceのGelkis VillageにいるMolkarに届ける。",
      out = "ゲルキスとの評判を維持し、ホワイト・バンディット・マスクをデソレースのゲルキス・ヴィレッジにいるモルカーに届ける。" },
    { id = "quest:9304:objectives", html = false,
      ja = "Smudged DocumentをEastern PlaguelandsのLight's Hope ChapelにいるKeeper of the Rollsのところへ持って行って下さい。",
      out = "スマッジド・ドキュメントをイースタン・プレイグランドのライツ・ホープ・チャペルにいるキーパー・オブ・ザ・ロールのところへ持って行って下さい。" },
    { id = "quest:93341:objectives", html = false,
      ja = "Shen'dralas近くのForlorn Gardensを調査し、その後近くの神殿にいるMitheraのところへ戻る。",
      out = "シェンドララス近くのフォーローン・ガーデンを調査し、その後近くの神殿にいるミセラのところへ戻る。" },
    { id = "quest:93733:objectives", html = false,
      ja = "ここにいるほかの者たちに自己紹介して下さい。見知らぬ者が作業を手伝っていても、驚かれないようにするためです。<PH>。",
      out = "ここにいるほかの者たちに自己紹介して下さい。見知らぬ者が作業を手伝っていても、驚かれないようにするためです。<ピーエイチ>。" },
    { id = "quest:940:title", html = false,
      ja = "Teldrassil",
      out = "テルドラシル" },
    { id = "quest:94275:title", html = false,
      ja = "Craftsman's Writ: Solid Sharpening Stone",
      out = "クラフツマンズ・リット: ソリッド・シャープニング・ストーン" },
    { id = "quest:94346:description", html = false,
      ja = "<色あせたインクで書かれたこのメモには、Runic Leather Headbandを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>",
      out = "<色あせたインクで書かれたこのメモには、ルーニック・レザー・ヘッドバンドを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>" },
    { id = "quest:94501:description", html = false,
      ja = "水のトーテムの儀式で報いる前に、Norricはあんたにもうひとつ仕事を頼むはずよ。私が渡した水の小瓶は、その仕事が何であれ必要になるの。さあ行って、彼を見つけて。またいつか会いましょう。",
      out = "水のトーテムの儀式で報いる前に、ノリックはあんたにもうひとつ仕事を頼むはずよ。私が渡した水の小瓶は、その仕事が何であれ必要になるの。さあ行って、彼を見つけて。またいつか会いましょう。" },
    { id = "quest:94864:objectives", html = false,
      ja = "Taming Rodを使ってYoung Forest Bearを手なずけてください。技を練習したら、Taming RodをJosephine Carsonに返してください。",
      out = "テイミング・ロッドを使ってヤング・フォレスト・ベアを手なずけてください。技を練習したら、テイミング・ロッドをジョセフィーヌ・カーソンに返してください。" },
    { id = "quest:94979:description", html = false,
      ja = "お前は川の這う者を手なずけられることを証明した。次は開けた土地で腕を試す時だ。Zephrasの平原には、風のように駆ける誇り高き翼のハンター、galestriderの鳴き声が響いている。\n\nこのTaming Rodを持って、一頭探し出せ。低地へ旅し、その信頼を勝ち取るのだ。\n\nこの先に待つ試練への準備ができていることを示してみせろ。",
      out = "お前は川の這う者を手なずけられることを証明した。次は開けた土地で腕を試す時だ。ゼフラスの平原には、風のように駆ける誇り高き翼のハンター、ゲイルストライダーの鳴き声が響いている。\n\nこのテイミング・ロッドを持って、一頭探し出せ。低地へ旅し、その信頼を勝ち取るのだ。\n\nこの先に待つ試練への準備ができていることを示してみせろ。" },
    { id = "quest:95189:description", html = false,
      ja = "<Lordaeronの紋章が描かれた、風雨にさらされた紋章だ。王国の滅亡後に残った遺物はごくわずかなので、Stormwindの誰かがぜひとも手に入れたがるだろう。>",
      out = "<ローデロンの紋章が描かれた、風雨にさらされた紋章だ。王国の滅亡後に残った遺物はごくわずかなので、ストームウィンドの誰かがぜひとも手に入れたがるだろう。>" },
    { id = "quest:95383:description", html = false,
      ja = "<Wharfmaster Steamfizzleはあなたが差し出した硬貨を調べている。>\n\nおっほう！あのFrizは新しい世代をしっかり育ててるねえ。お待たせしてすみませんね、お客さん。町の誰かに木箱を届けに来たんだろう？そんなことは何も知らないけど、もし知ってたら、波止場のTazzikに話しに行くだろうね。あいつはそういうことに興味があるみたいだから。\n\nでも、手早く頼むよ、いいね？みんなに妙な勘違いをされちゃ困るからさ。",
      out = "<ワーフマスター・スチームフィズルはあなたが差し出した硬貨を調べている。>\n\nおっほう！あのフリズは新しい世代をしっかり育ててるねえ。お待たせしてすみませんね、お客さん。町の誰かに木箱を届けに来たんだろう？そんなことは何も知らないけど、もし知ってたら、波止場のタズィックに話しに行くだろうね。あいつはそういうことに興味があるみたいだから。\n\nでも、手早く頼むよ、いいね？みんなに妙な勘違いをされちゃ困るからさ。" },
    { id = "quest:95775:title", html = false,
      ja = "Drowned City",
      out = "ドラウンド・シティ" },
    { id = "quest:959:progress", html = false,
      ja = "Mad Magglishがあの99-year-old portを持ち逃げしてから、港湾長にずっと文句を言われっぱなしなんだ。どうやらあのボトルは、他でもないBaron Revilgaz本人からGazloweへの贈り物だったらしい。\n\nMad Magglishを探し出してそのportを取り戻す度胸と根気があるなら、たっぷり報酬を出すよう取り計らうよ。",
      out = "マッド・マグリッシュがあの99-イヤー・オールド・ポートを持ち逃げしてから、港湾長にずっと文句を言われっぱなしなんだ。どうやらあのボトルは、他でもないバロン・レヴィルガズ本人からガズロウへの贈り物だったらしい。\n\nマッド・マグリッシュを探し出してそのポートを取り戻す度胸と根気があるなら、たっぷり報酬を出すよう取り計らうよ。" },
    { id = "quest:96209:title", html = false,
      ja = "Ancient、Orokai",
      out = "エンシェント、オロカイ" },
    { id = "quest:96634:description", html = false,
      ja = "で、キャンプについてもっと知りたいってわけか？ いいことだ、{class}。どんな冒険者もまず最初にやるべきことは、料理人になって焚き火の起こし方を覚えることさ。\n\nCookingってのは、うまいものを作るだけじゃない。野営地の土台でもあるんだ。",
      out = "で、キャンプについてもっと知りたいってわけか？ いいことだ、{class}。どんな冒険者もまず最初にやるべきことは、料理人になって焚き火の起こし方を覚えることさ。\n\nクッキングってのは、うまいものを作るだけじゃない。野営地の土台でもあるんだ。" },
    { id = "quest:96914:objectives", html = false,
      ja = "Warsong Gulchで敵対勢力のプレイヤーを25人倒して下さい。",
      out = "ウォーソング・ガルチで敵対勢力のプレイヤーを25人倒して下さい。" },
    { id = "quest:97184:description", html = false,
      ja = "次に、お前の最後の試練に欠かせないDivination Scryerを組み立てねばならない。お前がTerrordaleで使ったexorcism censerがその触媒となる。占いの装置にふさわしい器は、私が作れるはずだ。\n\nだが、最後に必要な部品は2つのダイヤモンドだ。白を1つ、黒を1つ。これはThe Forsakenのパラディンとしての我らの本質の二面性を表している。この2つが道しるべとなり、scryerが生者と死者を隔てる帳を貫くのだ。",
      out = "次に、お前の最後の試練に欠かせないディビネーション・スクライヤーを組み立てねばならない。お前がテラーデイルで使ったエクソシズム・センサーがその触媒となる。占いの装置にふさわしい器は、私が作れるはずだ。\n\nだが、最後に必要な部品は2つのダイヤモンドだ。白を1つ、黒を1つ。これはフォーセイクンのパラディンとしての我らの本質の二面性を表している。この2つが道しるべとなり、スクライヤーが生者と死者を隔てる帳を貫くのだ。" },
    { id = "quest:97329:completion", html = false,
      ja = "それが鍵か？\n\n<Zimmixは檻の前面に向かって飛びかかり、何度もあなたの手から鍵をひったくろうとする。>\n\nいいから渡せって！",
      out = "それが鍵か？\n\n<ジミックスは檻の前面に向かって飛びかかり、何度もあなたの手から鍵をひったくろうとする。>\n\nいいから渡せって！" },
    { id = "quest:97908:description", html = false,
      ja = "倒れた獣から皮をうまく剥ぎ取れるってのは、冒険者が持てる中でもかなり価値のある技なんだ。\n\n野営地用のCamp Chairの作り方を教えてくれる奴を知ってるよ。ときには腰を下ろしてひと休みするのも大事でね、集めた皮を使えば、座り心地のいい椅子が作れる。少しくつろげば、最高の調子を保てるし、次に揉め事に巻き込まれた時には、ここぞというところで一撃を加えられるってもんだ。",
      out = "倒れた獣から皮をうまく剥ぎ取れるってのは、冒険者が持てる中でもかなり価値のある技なんだ。\n\n野営地用のキャンプ・チェアの作り方を教えてくれる奴を知ってるよ。ときには腰を下ろしてひと休みするのも大事でね、集めた皮を使えば、座り心地のいい椅子が作れる。少しくつろげば、最高の調子を保てるし、次に揉め事に巻き込まれた時には、ここぞというところで一撃を加えられるってもんだ。" },
    { id = "quest:97957:completion", html = false,
      ja = "これで、自分だけのIncense Candleを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。",
      out = "これで、自分だけのインセンス・キャンドルを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。" },
    { id = "quest:98109:objectives", html = false,
      ja = "Quel'Thalasへ向かう道沿い、Northdaleの廃墟の北西にいるハイエルフのAdonと話す。",
      out = "ケルサラスへ向かう道沿い、ノースデイルの廃墟の北西にいるハイエルフのアドンと話す。" },
    { id = "quest:98326:title", html = false,
      ja = "Frosthowl",
      out = "フロストハウル" },
    { id = "quest:98685:objectives", html = false,
      ja = "Libram of Bindingと、Pristine Black Diamondを1個、Large Brilliant Shardsを2個、Arcane Crystalを1個、Dire MaulのLorekeeper Lydrosのもとへ持っていき、Arcanum of Bindingを受け取る。",
      out = "リブラム・オブ・バインディングと、プリスティン・ブラック・ダイヤモンドを1個、ラージ・ブリリアント・シャードを2個、アーケイン・クリスタルを1個、ダイア・モールのロアキーパー・ライドロスのもとへ持っていき、アルカナム・オブ・バインディングを受け取る。" },
    { id = "quest:99128:objectives", html = false,
      ja = "Crystal LakeでMurlocを$N1体とMurloc Streamrunnerを$N2体倒し、Jason Mathersのところへ戻ってください。",
      out = "クリスタル・レイクでマーロックを$N1体とマーロック・ストリームランナーを$N2体倒し、ジェイソン・マザーズのところへ戻ってください。" },
    { id = "spell:1003:description", html = false,
      ja = "Shadow Word: Befuddle（Rank 2）を習得します。",
      out = "シャドウ・ワード: ビファドル（ランク 2）を習得します。" },
    { id = "spell:10537:description", html = false,
      ja = "術者の足元に体力$N1のFire Resistance Totemを$D1の間召喚します。トーテムは$N3ヤード以内のパーティまたはレイドメンバーの火炎抵抗を$N4上昇させます。",
      out = "術者の足元に体力$N1のファイア・レジスタンス・トーテムを$D1の間召喚します。トーテムは$N3ヤード以内のパーティまたはレイドメンバーの火炎抵抗を$N4上昇させます。" },
    { id = "spell:11089:aura", html = false,
      ja = "Shadowダメージに対する免疫があります。\r\nPhysicalダメージに対する免疫があります。",
      out = "シャドウダメージに対する免疫があります。\r\nフィジカルダメージに対する免疫があります。" },
    { id = "spell:11675:description", html = false,
      ja = "対象の魂を吸い取り、$D1かけて$N1のShadowダメージを与えます。Drain Soulでダメージを受けた、経験値か名誉を得られる対象は、Soul Shardをもたらすことがあります。Drain Soulで倒された、経験値か名誉を得られる対象は、必ずSoul Shardをもたらします。Soul Shardは他の呪文に必要です。",
      out = "対象の魂を吸い取り、$D1かけて$N1のシャドウダメージを与えます。ドレイン・ソウルでダメージを受けた、経験値か名誉を得られる対象は、ソウル・シャードをもたらすことがあります。ドレイン・ソウルで倒された、経験値か名誉を得られる対象は、必ずソウル・シャードをもたらします。ソウル・シャードは他の呪文に必要です。" },
    { id = "spell:1213276:description", html = false,
      ja = "敵にFrostダメージを与え、$D1の間、移動速度を低下させます。",
      out = "敵にフロストダメージを与え、$D1の間、移動速度を低下させます。" },
    { id = "spell:1214918:description", html = false,
      ja = "Weapon Damageが$N1上昇します。",
      out = "ウェポン・ダメージが$N1上昇します。" },
    { id = "spell:1219153:description", html = false,
      ja = "敵に印を付けます。その敵がダメージを与えるたびに、その対象は最大体力の$N1%を回復します。効果時間は$D1、または最大$N3回の命中までです。\n\nアンデッドの対象ではスタックが減りません。一体の対象に有効にできるMark of Bloodは一度に一つだけです。",
      out = "敵に印を付けます。その敵がダメージを与えるたびに、その対象は最大体力の$N1%を回復します。効果時間は$D1、または最大$N3回の命中までです。\n\nアンデッドの対象ではスタックが減りません。一体の対象に有効にできるマーク・オブ・ブラッドは一度に一つだけです。" },
    { id = "spell:1219815:description", html = false,
      ja = "肩にSoul of the Alpha Tamerを永続的に宿らせます：\r\n\nペットのFocus回復速度が$N1%増加します。",
      out = "肩にソウル・オブ・ザ・アルファ・テイマーを永続的に宿らせます：\r\n\nペットのフォーカス回復速度が$N1%増加します。" },
    { id = "spell:1219966:description", html = false,
      ja = "Slamが命中すると、Mortal Strike、Bloodthirst、Shield Slamの残りクールダウンがリセットされます。",
      out = "スラムが命中すると、モータル・ストライク、ブラッドサースト、シールド・スラムの残りクールダウンがリセットされます。" },
    { id = "spell:1220293:description", html = false,
      ja = "Lava Burstのダメージが、呪文のクリティカル率と同じ割合だけ増加します。",
      out = "ラヴァ・バーストのダメージが、呪文のクリティカル率と同じ割合だけ増加します。" },
    { id = "spell:1223372:aura", html = false,
      ja = "Naxxramasの中にいる間、あなたの潜在能力を解放します。装備しているSanctifiedアイテム一つにつき、生み出す脅威が$N1%、与えるダメージが$N2%、体力が$N3%増加します。",
      out = "ナクスラーマスの中にいる間、あなたの潜在能力を解放します。装備しているサンクティファイドアイテム一つにつき、生み出す脅威が$N1%、与えるダメージが$N2%、体力が$N3%増加します。" },
    { id = "spell:1226591:description", html = false,
      ja = "Mind Blastの発生させる脅威が$N1%減少し、対象にかかっているMind Spikeのスタック一つにつきダメージが$N2%増加します。",
      out = "マインド・ブラストの発生させる脅威が$N1%減少し、対象にかかっているマインド・スパイクのスタック一つにつきダメージが$N2%増加します。" },
    { id = "spell:1230948:description", html = false,
      ja = "攻撃呪文のGlobal Cooldownが$N1秒短縮されます。",
      out = "攻撃呪文のグローバル・クールダウンが$N1秒短縮されます。" },
    { id = "spell:1231906:description", html = false,
      ja = "BalnazzarがinfernalをScarlet Lightbearerの妨害に呼び出し、$N2ヤード以内に$N1のFireダメージを与え、命中したプレイヤーを$N3の間スタンさせます。",
      out = "バルナザールがインファーナルをスカーレット・ライトベアラーの妨害に呼び出し、$N2ヤード以内に$N1のファイアダメージを与え、命中したプレイヤーを$N3の間スタンさせます。" },
    { id = "spell:1235320:description", html = false,
      ja = "$?a435884[命中時に一定の確率で、次の$N1回のNatureダメージが$N2%増加します。$D1持続します。]?a446658[命中時に一定の確率で、次の$N4回のCleaveダメージが$N5%増加します。$D2持続します。]?a446374[命中時に一定の確率で、次の$N7回のRaptor Strikeのダメージが$N8%増加します。$D3持続します。]?a462814[命中時に一定の確率で、次の$N10回のHolyダメージが$N11%増加します。$D4持続します。][Crimson Cleaverはあなたの存在に反応しません。別のクラスなら恩恵を受けられるのではないでしょうか？]",
      out = "$?a435884[命中時に一定の確率で、次の$N1回のネイチャーダメージが$N2%増加します。$D1持続します。]?ア446658[命中時に一定の確率で、次の$N4回のクリーヴダメージが$N5%増加します。$D2持続します。]?ア446374[命中時に一定の確率で、次の$N7回のラプター・ストライクのダメージが$N8%増加します。$D3持続します。]?ア462814[命中時に一定の確率で、次の$N10回のホーリーダメージが$N11%増加します。$D4持続します。][クリムゾン・クリーヴァーはあなたの存在に反応しません。別のクラスなら恩恵を受けられるのではないでしょうか？]" },
    { id = "spell:1241797:description", html = false,
      ja = "ダメージを与えるフィニッシュ技を使うと、Adrenaline Rush、Blade Flurry、Evasion、Sprint、Vanishの残りクールダウンがコンボポイントごとに$D1短縮されます。",
      out = "ダメージを与えるフィニッシュ技を使うと、アドレナリン・ラッシュ、ブレード・フラリー、イベイジョン、スプリント、バニッシュの残りクールダウンがコンボポイントごとに$D1短縮されます。" },
    { id = "spell:1248760:description", html = false,
      ja = "Melee Weaponに永続的なエンチャントを施し、攻撃をParriedまたはDodgedされたときにRecoveryが発動するようにします。Recoveryは最大体力の$N1%を回復します。この効果は$N2秒に一度までしか発生しません。",
      out = "メレー・ウェポンに永続的なエンチャントを施し、攻撃をパリードまたはドッジドされたときにリカバリーが発動するようにします。リカバリーは最大体力の$N1%を回復します。この効果は$N2秒に一度までしか発生しません。" },
    { id = "spell:1253387:aura", html = false,
      ja = "Fire耐性が$N1上昇します。",
      out = "ファイア耐性が$N1上昇します。" },
    { id = "spell:1263261:description", html = false,
      ja = "$N1のPhysicalダメージを与え、ターゲットに棘を埋め込みます。棘により、受ける近接攻撃のダメージがさらに$N2のPhysicalダメージ分増加します。",
      out = "$N1のフィジカルダメージを与え、ターゲットに棘を埋め込みます。棘により、受ける近接攻撃のダメージがさらに$N2のフィジカルダメージ分増加します。" },
    { id = "spell:1269554:description", html = false,
      ja = "近くの敵に取り憑き、Shadowダメージを与えます。",
      out = "近くの敵に取り憑き、シャドウダメージを与えます。" },
    { id = "spell:12733:description", html = false,
      ja = "すべてのResistanceを$N1上げ、$D1の間FearへのImmunityを与えます。",
      out = "すべてのレジスタンスを$N1上げ、$D1の間フィアーへのイミュニティーを与えます。" },
    { id = "spell:1286114:description", html = false,
      ja = "Anaraが$D2の間、$D1ごとにランダムなプレイヤーの位置に星を降らせます。それぞれの星は着弾地点から$N4ヤード以内のすべてのプレイヤーに$N3のArcaneダメージを与えます。",
      out = "アナラが$D2の間、$D1ごとにランダムなプレイヤーの位置に星を降らせます。それぞれの星は着弾地点から$N4ヤード以内のすべてのプレイヤーに$N3のアーケインダメージを与えます。" },
    { id = "spell:1290120:aura", html = false,
      ja = "By'zaaliの子があなたの献身を認め、ふさわしい者と見なしました。",
      out = "バイザーリの子があなたの献身を認め、ふさわしい者と見なしました。" },
    { id = "spell:1293695:description", html = false,
      ja = "Searing Painが生み出す脅威が$N1%減少し、$D1の間対象に烙印を押します。ペットの次の$N3回の対象への攻撃は、ペットに応じて$N4のFireまたはShadowダメージを与えます。Shadowダメージを与えた場合、高い脅威を生みます。",
      out = "シアリング・ペインが生み出す脅威が$N1%減少し、$D1の間対象に烙印を押します。ペットの次の$N3回の対象への攻撃は、ペットに応じて$N4のファイアまたはシャドウダメージを与えます。シャドウダメージを与えた場合、高い脅威を生みます。" },
    { id = "spell:1295608:description", html = false,
      ja = "点火した者からCurseまたはBaneを$N1個、Diseaseを$N2個取り除こうと試みます。",
      out = "点火した者からカースまたはベインを$N1個、ディジーズを$N2個取り除こうと試みます。" },
    { id = "spell:1300821:aura", html = false,
      ja = "$D1ごとにArcaneダメージを受けています。",
      out = "$D1ごとにアーケインダメージを受けています。" },
    { id = "spell:1302833:description", html = false,
      ja = "$D1の間、移動速度が$N1%上昇します。Desert地域で戦闘外にいる間は、さらに移動速度が$N3%上昇し、透明になります。",
      out = "$D1の間、移動速度が$N1%上昇します。デザート地域で戦闘外にいる間は、さらに移動速度が$N3%上昇し、透明になります。" },
    { id = "spell:1307208:description", html = false,
      ja = "アンデッドへのShockの詠唱で、Stormstrikeの残りクールダウンが$D1短縮されます。",
      out = "アンデッドへのショックの詠唱で、ストームストライクの残りクールダウンが$D1短縮されます。" },
    { id = "spell:1309551:aura", html = false,
      ja = "受けるFireダメージが$N1%増加しています。\n移動速度が$N2%上昇しています。",
      out = "受けるファイアダメージが$N1%増加しています。\n移動速度が$N2%上昇しています。" },
    { id = "spell:1314104:description", html = false,
      ja = "Seal of Furyのシールドが完全に吸収されると、マナを$N1回復します。この量は攻撃者のレベルがあなたを上回るレベルごとに$N2%増え、最大$N3%まで増えます。",
      out = "シール・オブ・フューリーのシールドが完全に吸収されると、マナを$N1回復します。この量は攻撃者のレベルがあなたを上回るレベルごとに$N2%増え、最大$N3%まで増えます。" },
    { id = "spell:13183:aura", html = false,
      ja = "$N2秒ごとに$N1のFireダメージを与えています。",
      out = "$N2秒ごとに$N1のファイアダメージを与えています。" },
    { id = "spell:1324895:description", html = false,
      ja = "NPCとのインタラクト範囲を上書きします。インタラクト用の呪文を使う必要があるクリーチャーだけでなく、クエストを与えるNPCにも有効です。",
      out = "エヌピーシーとのインタラクト範囲を上書きします。インタラクト用の呪文を使う必要があるクリーチャーだけでなく、クエストを与えるエヌピーシーにも有効です。" },
    { id = "spell:13398:description", html = false,
      ja = "敵にレンチを投げつけ、Physicalダメージを与えます。",
      out = "敵にレンチを投げつけ、フィジカルダメージを与えます。" },
    { id = "spell:13896:description", html = false,
      ja = "プリーストが反魔法のエネルギーに包まれます。プリーストに対して呪文が成功するたびに、攻撃者のマナを$N1焼却し、焼却したマナのポイントごとに$N2のShadowダメージを与えます。効果時間は$D1です。",
      out = "プリーストが反魔法のエネルギーに包まれます。プリーストに対して呪文が成功するたびに、攻撃者のマナを$N1焼却し、焼却したマナのポイントごとに$N2のシャドウダメージを与えます。効果時間は$D1です。" },
    { id = "spell:14331:description", html = false,
      ja = "$D2の間、$D1ごとに敵にPhysicalダメージを与えます。",
      out = "$D2の間、$D1ごとに敵にフィジカルダメージを与えます。" },
    { id = "spell:14664:description", html = false,
      ja = "Arcane Resistanceが$N1上昇します。",
      out = "アーケイン・レジスタンスが$N1上昇します。" },
    { id = "spell:14995:description", html = false,
      ja = "Shadow Resistanceが$N1上昇します。",
      out = "シャドウ・レジスタンスが$N1上昇します。" },
    { id = "spell:15574:description", html = false,
      ja = "敵にFireダメージを与えます。",
      out = "敵にファイアダメージを与えます。" },
    { id = "spell:15888:description", html = false,
      ja = "Macesが+$N1上昇します。",
      out = "メイスが+$N1上昇します。" },
    { id = "spell:16266:description", html = false,
      ja = "Rockbiter Weaponの近接攻撃力ボーナスを$N1%、Windfury Weaponの効果を$N2%増加させ、Flametongue WeaponとFrostbrand Weaponで与えるダメージを$N3%増加させます。",
      out = "ロックバイター・ウェポンの近接攻撃力ボーナスを$N1%、ウィンドフューリー・ウェポンの効果を$N2%増加させ、フレイムタン・ウェポンとフロストブランド・ウェポンで与えるダメージを$N3%増加させます。" },
    { id = "spell:16858:description", html = false,
      ja = "Demoralizing RoarによるAttack Power低下を$N1%、Ferocious Biteで与えるダメージを$N2%増加させます。",
      out = "ディモラライジング・ロアによるアタック・パワー低下を$N1%、フェロシャス・バイトで与えるダメージを$N2%増加させます。" },
    { id = "spell:17293:description", html = false,
      ja = "敵をスタンさせ、$D1かけて$N1のFireダメージを与えます。",
      out = "敵をスタンさせ、$D1かけて$N1のファイアダメージを与えます。" },
    { id = "spell:17819:description", html = false,
      ja = "Nature呪文と効果によるダメージが最大$N1増加します。",
      out = "ネイチャー呪文と効果によるダメージが最大$N1増加します。" },
    { id = "spell:18015:description", html = false,
      ja = "Shadow呪文と効果によるダメージが最大$N1増加します。",
      out = "シャドウ呪文と効果によるダメージが最大$N1増加します。" },
    { id = "spell:18499:description", html = false,
      ja = "ウォリアーが狂戦士の怒りに入り、FearとIncapacitateの効果を無効にし、ダメージを受けたときに追加の怒りを生み出します。効果時間は$D1です。",
      out = "ウォリアーが狂戦士の怒りに入り、フィアーとインキャパシテイトの効果を無効にし、ダメージを受けたときに追加の怒りを生み出します。効果時間は$D1です。" },
    { id = "spell:19184:description", html = false,
      ja = "罠が作動すると、効果を受けたすべての対象がEntrappedになり、$N1秒間移動できなくなります。",
      out = "罠が作動すると、効果を受けたすべての対象がエントラップトになり、$N1秒間移動できなくなります。" },
    { id = "spell:19674:description", html = false,
      ja = "Large Crag Boarの手なずけを開始し、$N1分間仲間にします。何らかの理由で獣の注意がそれると、手なずけは失敗します。",
      out = "ラージ・クラッグ・ボアの手なずけを開始し、$N1分間仲間にします。何らかの理由で獣の注意がそれると、手なずけは失敗します。" },
    { id = "spell:20028:description", html = false,
      ja = "chestに知力を$N1上昇させる永続的な\n魔力付与を行います。",
      out = "チェストに知力を$N1上昇させる永続的な\n魔力付与を行います。" },
    { id = "spell:20393:description", html = false,
      ja = "Voidwalker Suffering（Rank $N1）を習得します。",
      out = "ヴォイドウォーカー・サファリング（ランク $N1）を習得します。" },
    { id = "spell:20757:description", html = false,
      ja = "Major Soulstoneを作成します。Soulstoneは対象1人の魂を保管するのに使用できます。魂が保管されている間に対象が死亡すると、体力 $N1、マナ $N2で復活できます。\n\n作成したアイテムは、$N3分を超えてログアウトすると消滅します。",
      out = "メジャー・ソウルストーンを作成します。ソウルストーンは対象1人の魂を保管するのに使用できます。魂が保管されている間に対象が死亡すると、体力 $N1、マナ $N2で復活できます。\n\n作成したアイテムは、$N3分を超えてログアウトすると消滅します。" },
    { id = "spell:21183:aura", html = false,
      ja = "受けるHolyダメージが最大$N1増加します。",
      out = "受けるホーリーダメージが最大$N1増加します。" },
    { id = "spell:21565:aura", html = false,
      ja = "現在『Shredding』中です。",
      out = "現在『シュレッディング』中です。" },
    { id = "spell:22582:description", html = false,
      ja = "敵にFrostダメージを与え、$D1の間、移動速度を低下させます。",
      out = "敵にフロストダメージを与え、$D1の間、移動速度を低下させます。" },
    { id = "spell:23131:description", html = false,
      ja = "$D1の間、Frost呪文を術者に跳ね返します。",
      out = "$D1の間、フロスト呪文を術者に跳ね返します。" },
    { id = "spell:23560:description", html = false,
      ja = "Mend Petの射程を$N1%、効果を$N2%増加させます。さらにコストを$N3%軽減します。",
      out = "メンド・ペットの射程を$N1%、効果を$N2%増加させます。さらにコストを$N3%軽減します。" },
    { id = "spell:24353:aura", html = false,
      ja = "Revive Petのマナコストが$N1%減少しています。",
      out = "リバイブ・ペットのマナコストが$N1%減少しています。" },
    { id = "spell:24583:aura", html = false,
      ja = "$N2秒ごとに$N1のNatureダメージを受けます。",
      out = "$N2秒ごとに$N1のネイチャーダメージを受けます。" },
    { id = "spell:25016:description", html = false,
      ja = "稲妻を吐き、単体の対象に即座に$N1のNatureダメージを与えます。",
      out = "稲妻を吐き、単体の対象に即座に$N1のネイチャーダメージを与えます。" },
    { id = "spell:25898:description", html = false,
      ja = "対象と同じクラスのレイドまたはグループのメンバー全員にGreater Blessing of Kingsを与え、$D1の間すべての能力値を$N1%上昇させます。プレイヤーが同時に受けられるBlessingは、パラディン一人につき一つだけです。",
      out = "対象と同じクラスのレイドまたはグループのメンバー全員にグレーター・ブレッシング・オブ・キングを与え、$D1の間すべての能力値を$N1%上昇させます。プレイヤーが同時に受けられるブレッシングは、パラディン一人につき一つだけです。" },
    { id = "spell:26452:description", html = false,
      ja = "術者をIronforgeへテレポートさせます。",
      out = "術者をアイアンフォージへテレポートさせます。" },
    { id = "spell:27602:description", html = false,
      ja = "Arcanite Dragonlingが動き出し、$D1の間あなたを守ります。",
      out = "アーケイナイト・ミニドラゴンが動き出し、$D1の間あなたを守ります。" },
    { id = "spell:28272:description", html = false,
      ja = "敵を豚に変え、最大$D1の間さまよわせます。さまよっている間、豚は攻撃も呪文の詠唱もできませんが、非常に速く回復します。ダメージを受けると元の姿に戻ります。一度にポリモーフできる対象は一体だけです。Beasts、Humanoids、Crittersにのみ有効です。",
      out = "敵を豚に変え、最大$D1の間さまよわせます。さまよっている間、豚は攻撃も呪文の詠唱もできませんが、非常に速く回復します。ダメージを受けると元の姿に戻ります。一度にポリモーフできる対象は一体だけです。ビースト、ヒューマノイド、クリッターにのみ有効です。" },
    { id = "spell:28853:description", html = false,
      ja = "Judgementで周囲のパーティメンバー全員を$N1回復させるようになります。",
      out = "ジャッジメントで周囲のパーティメンバー全員を$N1回復させるようになります。" },
    { id = "spell:3068:description", html = false,
      ja = "Blizzard（Rank 2）を習得します。",
      out = "ブリザード（ランク 2）を習得します。" },
    { id = "spell:3611:description", html = false,
      ja = "$D1の間、術者を戦闘で援護するMinion of Morganthを$N1体召喚します。",
      out = "$D1の間、術者を戦闘で援護するミニオン・オブ・モーガンスを$N1体召喚します。" },
    { id = "spell:400038:description", html = false,
      ja = "Blade Danceのアビリティを得ます：\n\n$I1\nフィニッシュ技です。Parryの確率を$N1%上昇させ、防御スキルが$N3を超えるポイントごとにAttack Powerを$N2得ます。コンボポイントが多いほど長く持続します：\n\n1ポイント：14秒\n 2ポイント：18秒\n 3ポイント：22秒\n 4ポイント：26秒\n 5ポイント：30秒",
      out = "ブレード・ダンスのアビリティを得ます：\n\n$I1\nフィニッシュ技です。パリーの確率を$N1%上昇させ、防御スキルが$N3を超えるポイントごとにアタック・パワーを$N2得ます。コンボポイントが多いほど長く持続します：\n\n1ポイント：14秒\n 2ポイント：18秒\n 3ポイント：22秒\n 4ポイント：26秒\n 5ポイント：30秒" },
    { id = "spell:402911:description", html = false,
      ja = "武器ダメージの$N1%を与える猛烈な一撃です。Enrage、Berserker Rage、Bloodrageのいずれかが有効な間のみ使用できます。Enrage、Berserker Rage、Bloodrageが有効な間に他の近接アビリティを使うたびに、Raging Blowの残りクールダウンが$N2秒短縮されます。",
      out = "武器ダメージの$N1%を与える猛烈な一撃です。エンレイジ、バーサーカー・レイジ、ブラッドレイジのいずれかが有効な間のみ使用できます。エンレイジ、バーサーカー・レイジ、ブラッドレイジが有効な間に他の近接アビリティを使うたびに、レイジング・ブローの残りクールダウンが$N2秒短縮されます。" },
    { id = "spell:408475:description", html = false,
      ja = "対象に雷の矢を放ち、$N1のNatureダメージを与えます。",
      out = "対象に雷の矢を放ち、$N1のネイチャーダメージを与えます。" },
    { id = "spell:411956:description", html = false,
      ja = "苦痛の呪いを対象にかけ、$D1かけて$N1のShadowダメージを与えます。このダメージは最初はゆっくりと与えられ、Curseが効果時間の終わりに近づくにつれて増していきます。",
      out = "苦痛の呪いを対象にかけ、$D1かけて$N1のシャドウダメージを与えます。このダメージは最初はゆっくりと与えられ、カースが効果時間の終わりに近づくにつれて増していきます。" },
    { id = "spell:415706:description", html = false,
      ja = "The Art of Warのアビリティを得ます：\n\n$I1\n与えるすべてのHolyダメージが$N1%増加し、近接攻撃と呪文のクリティカルによりExorcismの呪文の残りクールダウンが$D1短縮されます。",
      out = "アート・オブ・ウォーのアビリティを得ます：\n\n$I1\n与えるすべてのホーリーダメージが$N1%増加し、近接攻撃と呪文のクリティカルによりエクソシズムの呪文の残りクールダウンが$D1短縮されます。" },
    { id = "spell:423299:description", html = false,
      ja = "物理攻撃でBeastsに与えるダメージを$N1増加させます。",
      out = "物理攻撃でビーストに与えるダメージを$N1増加させます。" },
    { id = "spell:426173:description", html = false,
      ja = "Judgementの射程が$N1ヤード延び、すべての呪文の呪文命中率が$N2%上昇します。",
      out = "ジャッジメントの射程が$N1ヤード延び、すべての呪文の呪文命中率が$N2%上昇します。" },
    { id = "spell:429255:description", html = false,
      ja = "手首にPurifying Powerのルーンを刻みます：\n\n$I1\nCleanseとPurifyのマナコストを$N1%減少させ、ExorcismとHoly Wrathのクールダウンを$N2%短縮します。",
      out = "手首にピュリファイイング・パワーのルーンを刻みます：\n\n$I1\nクレンズとピュリファイのマナコストを$N1%減少させ、エクソシズムとホーリー・ラスのクールダウンを$N2%短縮します。" },
    { id = "spell:432147:description", html = false,
      ja = "対象に稲妻を放ち、$N1のNatureダメージを与えます。",
      out = "対象に稲妻を放ち、$N1のネイチャーダメージを与えます。" },
    { id = "spell:435933:description", html = false,
      ja = "Goblin Mortarsを$N1個加えて、出荷品を完成させます。",
      out = "ゴブリン・モーターを$N1個加えて、出荷品を完成させます。" },
    { id = "spell:437480:aura", html = false,
      ja = "$D1ごとに$N3ヤード以内の味方に$N1のShadowダメージを与えています。この効果はスタックします。",
      out = "$D1ごとに$N3ヤード以内の味方に$N1のシャドウダメージを与えています。この効果はスタックします。" },
    { id = "spell:440496:description", html = false,
      ja = "外套にShockwaveのルーンを刻みます：\n\n$I1\nウォリアーの前方に衝撃波を放ち、$N1のダメージを与え、前方の円錐範囲$N2ヤード以内のすべての敵を$D1の間スタンさせます。",
      out = "外套にショックウェーブのルーンを刻みます：\n\n$I1\nウォリアーの前方に衝撃波を放ち、$N1のダメージを与え、前方の円錐範囲$N2ヤード以内のすべての敵を$D1の間スタンさせます。" },
    { id = "spell:4447:description", html = false,
      ja = "Two-Handed Axesでのダメージが$N1増加します。",
      out = "ツー・ハンデッド・アックスでのダメージが$N1増加します。" },
    { id = "spell:446891:description", html = false,
      ja = "Spirit of Agamagganを召喚します。Razorfen DownsのSpiral of Thornsの頂上で、近くの敵をすべて倒した後にのみ使用できます。",
      out = "スピリット・オブ・アガマガンを召喚します。レイザーフェン・ダウンのスパイラル・オブ・ソーンの頂上で、近くの敵をすべて倒した後にのみ使用できます。" },
    { id = "spell:454017:description", html = false,
      ja = "Fel ScarまたはRiftを、Legionの支配する宇宙の奥深くにある世界とつなげます。予測できない危険な効果が起こるかもしれません。",
      out = "フェル・スカーまたはリフトを、レギオンの支配する宇宙の奥深くにある世界とつなげます。予測できない危険な効果が起こるかもしれません。" },
    { id = "spell:459232:description", html = false,
      ja = "Dalton's Hornを吹き鳴らして従者を呼び出します。従者は戦闘であなたを助け、共に冒険するうちにあなたから学んでいきます。",
      out = "ダルトンズ・ホーンを吹き鳴らして従者を呼び出します。従者は戦闘であなたを助け、共に冒険するうちにあなたから学んでいきます。" },
    { id = "spell:461298:description", html = false,
      ja = "Stormstrike呪文を使うと、$D1の間、攻撃力が$N1上昇します。（両手武器を使うとより効果的です）。",
      out = "ストームストライク呪文を使うと、$D1の間、攻撃力が$N1上昇します。（両手武器を使うとより効果的です）。" },
    { id = "spell:463448:description", html = false,
      ja = "近くの敵にFrostダメージを与え、最大$D1の間、動けなくします。",
      out = "近くの敵にフロストダメージを与え、最大$D1の間、動けなくします。" },
    { id = "spell:467518:description", html = false,
      ja = "ダメージを与えるJudgementsのダメージが$N1%増加し、Judgementsが対象にかかったSealsを消費しなくなります。複数のSealが有効なとき、Judgementsでそれらすべてを発動できるようになります。",
      out = "ダメージを与えるジャッジメントのダメージが$N1%増加し、ジャッジメントが対象にかかったシールを消費しなくなります。複数のシールが有効なとき、ジャッジメントでそれらすべてを発動できるようになります。" },
    { id = "spell:468563:description", html = false,
      ja = "Gri'lek's Blood、Renataki's Tooth、Wushoolay's Mane、Hazza'rah's Dream Threadと組み合わせて、強力な護符を作ります。",
      out = "グリレクス・ブラッド、レナタキズ・トゥース、ウシューレイズ・メイン、ハザラズ・ドリーム・スレッドと組み合わせて、強力な護符を作ります。" },
    { id = "spell:470743:description", html = false,
      ja = "対象に稲妻を放ち、$N1のNatureダメージを与えます。",
      out = "対象に稲妻を放ち、$N1のネイチャーダメージを与えます。" },
    { id = "spell:4882:description", html = false,
      ja = "Shadow呪文のダメージが$N1増加します。",
      out = "シャドウ呪文のダメージが$N1増加します。" },
    { id = "spell:5413:aura", html = false,
      ja = "Nature耐性が$N1低下しています。",
      out = "ネイチャー耐性が$N1低下しています。" },
    { id = "spell:5822:description", html = false,
      ja = "Nature Magicスキルが$N1増加しますが、ShadowとFireの耐性が$N2低下します。",
      out = "ネイチャー・マジックスキルが$N1増加しますが、シャドウとファイアの耐性が$N2低下します。" },
    { id = "spell:6356:description", html = false,
      ja = "Felhunterは魔法に対して無敵です。",
      out = "フェルハンターは魔法に対して無敵です。" },
    { id = "spell:710:description", html = false,
      ja = "敵対象を追放し、最大$D1の間あらゆる行動を封じますが、その間は無敵になります。一度に追放できる対象は一体だけです。DemonsとElementalsにのみ有効です。",
      out = "敵対象を追放し、最大$D1の間あらゆる行動を封じますが、その間は無敵になります。一度に追放できる対象は一体だけです。デーモンとエレメンタルにのみ有効です。" },
    { id = "spell:7620:description", html = false,
      ja = "釣り竿を装備し、魚のいる水域を\n見つけてください。魚を釣り上げる\nために、魚が跳ねたら、水上の浮き\n(bob)を右クリックして下さい。\nスキルが高くなると、高レベルな\n釣り場での成功率が上がります。",
      out = "釣り竿を装備し、魚のいる水域を\n見つけてください。魚を釣り上げる\nために、魚が跳ねたら、水上の浮き\n(ボブ)を右クリックして下さい。\nスキルが高くなると、高レベルな\n釣り場での成功率が上がります。" },
    { id = "spell:8087:description", html = false,
      ja = "釣り竿に使用すると、10分間Fishingを25上げます。",
      out = "釣り竿に使用すると、10分間フィッシングを25上げます。" },
    { id = "spell:850:description", html = false,
      ja = "Pummel（Learn）の習得。",
      out = "パンメル（ラーン）の習得。" },
    { id = "spell:9305:description", html = false,
      ja = "Frost呪文と効果によるダメージが最大$N1増加します。",
      out = "フロスト呪文と効果によるダメージが最大$N1増加します。" },
  },
}
